  function validateCareerUnlockCatalog() {
    if (!careerUnlockCatalog) return true;
    var gameClassIds = Object.keys(PLAYER_CLASSES).sort();
    var catalogClassIds = (careerUnlockCatalog.classes || [])
      .map(function (spec) { return spec.id; })
      .sort();
    var gameBranchClasses = Object.create(null);
    Object.keys(REVOLVER_UPGRADES).forEach(function (id) { gameBranchClasses[id] = "gunslinger"; });
    Object.keys(RIFLE_UPGRADES).forEach(function (id) { gameBranchClasses[id] = "ranger"; });
    Object.keys(LAUNCHER_UPGRADES).forEach(function (id) { gameBranchClasses[id] = "demolitionist"; });
    Object.keys(MARSHAL_UPGRADES).forEach(function (id) { gameBranchClasses[id] = "marshal"; });
    var gameBranchIds = Object.keys(gameBranchClasses).sort();
    var catalogBranches = careerUnlockCatalog.branches || [];
    var catalogBranchIds = catalogBranches.map(function (spec) { return spec.id; }).sort();
    if (
      catalogClassIds.length !== gameClassIds.length ||
      gameClassIds.some(function (id, index) { return id !== catalogClassIds[index]; }) ||
      catalogBranchIds.length !== gameBranchIds.length ||
      gameBranchIds.some(function (id, index) { return id !== catalogBranchIds[index]; }) ||
      catalogBranches.some(function (spec) {
        return gameBranchClasses[spec.id] !== spec.classId;
      })
    ) {
      throw new Error("Dust & Dead class/mastery registry is out of sync with progression unlocks.");
    }
    var gameIds = getAllRunUpgradeSpecs().map(function (spec) { return spec.id; }).sort();
    var catalogIds = careerUnlockCatalog.cards.map(function (spec) { return spec.id; }).sort();
    if (
      gameIds.length !== 86 ||
      catalogIds.length !== gameIds.length ||
      gameIds.some(function (id, index) { return id !== catalogIds[index]; })
    ) {
      throw new Error("Dust & Dead run-card registry is out of sync with the progression unlock catalog.");
    }
    return true;
  }

  validateCareerUnlockCatalog();

  function createFullCareerUnlockProfile() {
    var classes = Object.keys(PLAYER_CLASSES);
    var branches = Object.keys(REVOLVER_UPGRADES)
      .concat(Object.keys(RIFLE_UPGRADES))
      .concat(Object.keys(LAUNCHER_UPGRADES))
      .concat(Object.keys(MARSHAL_UPGRADES));
    var purchasedCards = careerUnlockCatalog
      ? careerUnlockCatalog.cards.filter(function (entry) { return !entry.core; }).map(function (entry) { return entry.id; })
      : getAllRunUpgradeSpecs().map(function (spec) { return spec.id; });
    return buildCareerUnlockProfile({
      version: 1,
      classes: classes,
      branches: branches,
      purchasedCards: purchasedCards,
      markedCards: [],
    });
  }

  function buildCareerUnlockProfile(source) {
    source = source && typeof source === "object" ? source : {};
    var normalized = careerProgression && typeof careerProgression.normalizeUnlockProfile === "function"
      ? careerProgression.normalizeUnlockProfile(source)
      : {
          version: 1,
          classes: Array.isArray(source.classes) ? source.classes.slice() : Object.keys(PLAYER_CLASSES),
          branches: Array.isArray(source.branches) ? source.branches.slice() : Object.keys(REVOLVER_UPGRADES)
            .concat(Object.keys(RIFLE_UPGRADES))
            .concat(Object.keys(LAUNCHER_UPGRADES))
            .concat(Object.keys(MARSHAL_UPGRADES)),
          purchasedCards: Array.isArray(source.purchasedCards)
            ? source.purchasedCards.slice()
            : getAllRunUpgradeSpecs().map(function (spec) { return spec.id; }),
          markedCards: Array.isArray(source.markedCards) ? source.markedCards.slice() : [],
        };
    var coreCards = careerUnlockCatalog
      ? careerUnlockCatalog.cards.filter(function (entry) { return entry.core; }).map(function (entry) { return entry.id; })
      : [];
    var cards = coreCards.concat(normalized.purchasedCards || []);
    var profile = {
      version: 1,
      classes: (normalized.classes || []).slice(),
      branches: (normalized.branches || []).slice(),
      purchasedCards: (normalized.purchasedCards || []).slice(),
      cards: cards,
      markedCards: (normalized.markedCards || []).slice(),
      classLookup: Object.create(null),
      branchLookup: Object.create(null),
      cardLookup: Object.create(null),
      markedLookup: Object.create(null),
    };
    profile.classes.forEach(function (id) { profile.classLookup[id] = true; });
    profile.branches.forEach(function (id) { profile.branchLookup[id] = true; });
    profile.cards.forEach(function (id) { profile.cardLookup[id] = true; });
    profile.markedCards.forEach(function (id) { profile.markedLookup[id] = true; });
    return profile;
  }

