    buildMenuCactus(-19.2, 1.4, 1.2);
    buildMenuCactus(-14.4, 10.8, 0.92);
    buildMenuCactus(17.8, 6.8, 1.08);
    buildMenuCactus(24.6, 1.1, 0.84);
