      audioState.sfxLimiter.knee.value = 10;
      audioState.sfxLimiter.ratio.value = 9;
      audioState.sfxLimiter.attack.value = 0.002;
      audioState.sfxLimiter.release.value = 0.16;
      audioState.menuGain.gain.value = 0;
      audioState.gameGain.gain.value = 0;
      audioState.gameNormalGain.gain.value = 1;
      audioState.gameBossGain.gain.value = 0.0001;
      audioState.gameExploreGain.gain.value = 1;
      audioState.gameBattleGain.gain.value = 0;
      audioState.bossMusicInput.gain.value = 1;
      audioState.bossMusicRhythmInput.gain.value = 1;
      audioState.bossMusicRhythmGain.gain.value = 0.86;
      audioState.bossMusicDryGain.gain.value = 0.78;
      audioState.bossMusicDelay.delayTime.value = 0.235;
      audioState.bossMusicFeedback.gain.value = 0.2;
