      audioState.bossMusicDryGain.connect(audioState.bossMusicLimiter);
      audioState.bossMusicRhythmInput.connect(audioState.bossMusicRhythmGain);
      audioState.bossMusicRhythmGain.connect(audioState.bossMusicLimiter);
      audioState.bossMusicInput.connect(audioState.bossMusicDelay);
      audioState.bossMusicDelay.connect(audioState.bossMusicLowpass);
      audioState.bossMusicLowpass.connect(audioState.bossMusicWetGain);
      audioState.bossMusicWetGain.connect(audioState.bossMusicLimiter);
