        hordeMainBeginsIn: Number(Math.max(0, (audioState.bossMusic.hordeMainBeginsAt || 0) - audioNow).toFixed(3)),
        arrangementSection: audioState.bossMusic.arrangementSection,
        lastStepEventCount: audioState.bossMusic.lastStepEventCount,
        peakStepEventCount: audioState.bossMusic.peakStepEventCount,
        skippedStepCount: audioState.bossMusic.skippedStepCount,
        railDensity: Number((audioState.bossMusic.railHitCount / Math.max(1, audioState.bossMusic.scheduledStepCount)).toFixed(3)),
        whistleDensity: Number((audioState.bossMusic.whistleCount / Math.max(1, audioState.bossMusic.scheduledStepCount)).toFixed(3)),
        deathStingCount: audioState.bossMusic.deathStingCount,
        persistentNodeCount: audioState.bossMusic.nodes.length,
        startCount: audioState.bossMusic.startCount,
