  function clearDynamic() {
    // Logical flashes are detached pooled data now. Clear them explicitly;
    // the four fixed scene lights must survive every run reset.
    releaseAllLightFlashesToPool();
    while (dynamicRoot.children.length) {
      var child = dynamicRoot.children[0];
      if (child.userData && child.userData.pooledZombie && child.userData.pooledZombie.pooled) {
        releaseZombieToPool(child.userData.pooledZombie);
      } else if (child.userData && child.userData.pooledPaleDeputy) {
        releasePaleDeputyEntity(child.userData.pooledPaleDeputy);
      } else {
        removeObject3D(child);
      }
    }
    while (effectRoot.children.length) {
      var effectChild = effectRoot.children[0];
      if (effectChild.userData && effectChild.userData.firePatchVisual) {
        releaseFirePatchVisual(effectChild.userData.firePatchVisual);
      } else if (effectChild.userData && effectChild.userData.marshalHallowedVisual) {
        releaseMarshalHallowedVisual(effectChild.userData.marshalHallowedVisual);
      } else if (effectChild.userData && effectChild.userData.rifleTrapInstancedBatch) {
        detachRifleTrapInstancedBatch(effectChild.userData.rifleTrapInstancedBatch);
      } else if (effectChild.userData && effectChild.userData.acidInstancedBatch) {
        detachAcidInstancedBatch(effectChild.userData.acidInstancedBatch);
      } else if (effectChild.userData && effectChild.userData.acidPuddleVisual) {
        releaseAcidPuddleVisual(effectChild.userData.acidPuddleVisual);
      } else if (effectChild.userData && effectChild.userData.acidProjectileInUse) {
        releaseAcidProjectileVisual(effectChild);
      } else if (effectChild.userData && effectChild.userData.deathDebrisInstancedBatch) {
        detachDeathDebrisInstancedBatch(effectChild.userData.deathDebrisInstancedBatch);
      } else if (effectChild.userData && effectChild.userData.rifleTrapVisual) {
        releaseRifleTrapVisual(effectChild.userData.rifleTrapVisual);
      } else if (effectChild.userData && effectChild.userData.particleVisual) {
        releaseParticleVisual(effectChild.userData.particleVisual);
      } else if (effectChild.userData && effectChild.userData.particleBatch) {
        detachParticleInstancedBatch(effectChild.userData.particleBatch);
      } else if (effectChild.userData && effectChild.userData.projectileStandardBatch) {
        detachStandardProjectileBatch(effectChild.userData.projectileStandardBatch);
      } else if (effectChild.userData && effectChild.userData.xpOrbVisual) {
        releaseXpOrbVisual(effectChild.userData.xpOrbVisual);
      } else if (effectChild.userData && effectChild.userData.deathDebrisVisual) {
        releaseDeathDebrisVisual(effectChild.userData.deathDebrisVisual);
      } else if (effectChild.userData && effectChild.userData.projectileVisual) {
        releaseProjectileVisual(effectChild.userData.projectileVisual);
      } else if (effectChild.userData && effectChild.userData.shockwaveVisual) {
        releaseShockwaveVisual(effectChild.userData.shockwaveVisual);
      } else if (effectChild.userData && effectChild.userData.smokePuffVisual) {
        releaseSmokePuffVisual(effectChild.userData.smokePuffVisual);
      } else if (effectChild.userData && effectChild.userData.scorchDecalVisual) {
        releaseScorchDecalVisual(effectChild.userData.scorchDecalVisual);
      } else if (effectChild.isLight && effectChild.userData && effectChild.userData.lightFlashVisual) {
        releaseLightFlashVisual(effectChild.userData.lightFlashVisual);
      } else if (effectChild.userData && effectChild.userData.lightningBoltVisual) {
        releaseLightningBoltVisual(effectChild.userData.lightningBoltVisual);
      } else {
        removeObject3D(effectChild);
      }
    }
  }

  function captureCowboyCosmeticAuthored(mesh) {
    if (!mesh) return mesh;
    mesh.userData.cosmeticAuthored = {
      position: mesh.position.clone(),
      rotation: mesh.rotation.clone(),
      scale: mesh.scale.clone(),
      geometry: mesh.geometry || null,
      material: mesh.material || null,
    };
    return mesh;
  }

  function restoreCowboyCosmeticAuthored(mesh) {
    if (!mesh || !mesh.userData.cosmeticAuthored) return;
    var authored = mesh.userData.cosmeticAuthored;
    mesh.position.copy(authored.position);
    mesh.rotation.copy(authored.rotation);
    mesh.scale.copy(authored.scale);
    if (authored.geometry) mesh.geometry = authored.geometry;
    if (authored.material) mesh.material = authored.material;
    if (mesh.userData.basePosition) mesh.userData.basePosition.copy(mesh.position);
    if (mesh.userData.baseRotation) mesh.userData.baseRotation.copy(mesh.rotation);
    if (mesh.userData.baseScale) mesh.userData.baseScale.copy(mesh.scale);
  }

  function setCowboyCosmeticTransform(mesh, position, rotation, scale) {
    if (!mesh) return;
    if (position) mesh.position.set(position[0], position[1], position[2]);
    if (rotation) mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
    if (scale) mesh.scale.set(scale[0], scale[1], scale[2]);
    if (mesh.userData.basePosition) mesh.userData.basePosition.copy(mesh.position);
    if (mesh.userData.baseRotation) mesh.userData.baseRotation.copy(mesh.rotation);
    if (mesh.userData.baseScale) mesh.userData.baseScale.copy(mesh.scale);
  }

  function captureCowboyAnimationPose(mesh) {
    if (
      !mesh ||
      !mesh.userData ||
      !mesh.userData.basePosition ||
      !mesh.userData.baseRotation
    ) return {};
    return {
      x: mesh.position.x - mesh.userData.basePosition.x,
      y: mesh.position.y - mesh.userData.basePosition.y,
      z: mesh.position.z - mesh.userData.basePosition.z,
      rx: mesh.rotation.x - mesh.userData.baseRotation.x,
      ry: mesh.rotation.y - mesh.userData.baseRotation.y,
      rz: mesh.rotation.z - mesh.userData.baseRotation.z,
    };
  }

  function applyCowboyCosmetics(group, source) {
    if (!group || !group.userData || !group.userData.animParts) {
      return normalizeCowboyCosmetics(source);
    }
    var cosmetics = normalizeCowboyCosmetics(source);
    var parts = group.userData.animParts;
    var cosmeticParts = group.userData.cosmeticParts || {};
    var outfit = mats.cowboyOutfits && mats.cowboyOutfits[cosmetics.cowboyId] ||
      mats.cowboyOutfits.trailwornDrifter;
    var hat = mats.cowboyHats && mats.cowboyHats[cosmetics.hatId] ||
      mats.cowboyHats.weatheredCattleman;
    // Cosmetic switching can happen mid-idle, mid-stride, or during recoil.
    // Preserve the two assembly poses while authored geometry/material state is
    // restored so a selected item never spends one frame detached from its body.
    var torsoAnimationPose = captureCowboyAnimationPose(parts.torso);
    var headAnimationPose = captureCowboyAnimationPose(parts.head);
    var leftArmAnimationPose = captureCowboyAnimationPose(parts.leftArm);
    var rightArmAnimationPose = captureCowboyAnimationPose(parts.rightArm);
    var activeWeaponVisualId = group.userData.activeWeaponVisualId;

    [
      parts.leftLeg,
      parts.rightLeg,
      parts.leftBoot,
      parts.rightBoot,
      parts.torso,
      parts.shirt,
      parts.leftArm,
      parts.rightArm,
      parts.belt,
      parts.scarf,
      parts.leftHolster,
      parts.rightHolster,
      parts.hatBrim,
      parts.hatTop,
      cosmeticParts.coatTailLeft,
      cosmeticParts.coatTailRight,
      cosmeticParts.bandolier,
      cosmeticParts.badge,
      cosmeticParts.poncho,
      cosmeticParts.hatBand,
      cosmeticParts.hatAccent,
    ].forEach(restoreCowboyCosmeticAuthored);

    parts.leftLeg.material = outfit.denim;
    parts.rightLeg.material = outfit.denim;
    parts.leftBoot.material = outfit.leather;
    parts.rightBoot.material = outfit.leather;
    parts.torso.material = outfit.coat;
    parts.shirt.material = outfit.shirt;
    parts.leftArm.material = outfit.sleeve;
    parts.rightArm.material = outfit.sleeve;
    parts.belt.material = outfit.leather;
    parts.scarf.material = outfit.scarf;
    parts.leftHolster.material = outfit.leather;
    parts.rightHolster.material = outfit.leather;

    [
      cosmeticParts.coatTailLeft,
      cosmeticParts.coatTailRight,
      cosmeticParts.bandolier,
      cosmeticParts.badge,
      cosmeticParts.poncho,
    ].forEach(function (mesh) {
      if (mesh) mesh.visible = false;
    });
    if (cosmeticParts.coatTailLeft) cosmeticParts.coatTailLeft.material = outfit.coat;
    if (cosmeticParts.coatTailRight) cosmeticParts.coatTailRight.material = outfit.coat;
    if (cosmeticParts.bandolier) cosmeticParts.bandolier.material = outfit.leather;
    if (cosmeticParts.badge) cosmeticParts.badge.material = mats.gold;
    if (cosmeticParts.poncho) cosmeticParts.poncho.material = outfit.scarf;

    if (cosmetics.cowboyId === "ashenProspector") {
      cosmeticParts.bandolier.visible = true;
    } else if (cosmetics.cowboyId === "mesaRanger") {
      cosmeticParts.poncho.visible = true;
    } else if (cosmetics.cowboyId === "crimsonLawman") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.badge.visible = true;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.36, 1.44, 0.53],
        null,
        [0.82, 0.82, 0.86]
      );
    } else if (cosmetics.cowboyId === "moonlitOutlaw") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.bandolier.visible = true;
    } else if (cosmetics.cowboyId === "gildedLegend") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.poncho.visible = true;
      cosmeticParts.badge.visible = true;
      // Pinned onto the poncho panel rather than buried inside it.
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.35, 1.44, 0.58],
        null,
        [0.82, 0.82, 0.86]
      );
    } else if (cosmetics.cowboyId === "baronsBlackGold") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.bandolier.visible = true;
      cosmeticParts.badge.visible = true;
      // The Baron's pin is brass rather than the marshal gold used elsewhere.
      cosmeticParts.badge.material = outfit.scarf;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.36, 1.44, 0.53],
        null,
        [0.82, 0.82, 0.86]
      );
    } else if (cosmetics.cowboyId === "livingBarrow") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.poncho.visible = true;
      cosmeticParts.badge.visible = true;
      // The badge doubles as the dim heart sunk into the chest wrappings.
      cosmeticParts.badge.material = outfit.shirt;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0, 1.4, 0.56],
        null,
        [0.9, 0.9, 0.7]
      );
    } else if (cosmetics.cowboyId === "lastSurveyor") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      // The poncho panel stands in for the jaw-toothed collar.
      cosmeticParts.poncho.visible = true;
    } else if (cosmetics.cowboyId === "lastParishVestments") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.bandolier.visible = true;
      // Gold rope over the cassock, not an ammo belt.
      cosmeticParts.bandolier.material = outfit.scarf;
    } else if (cosmetics.cowboyId === "doomConductor") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.badge.visible = true;
      // Brass conductor's badge cut from the scarf fittings.
      cosmeticParts.badge.material = outfit.scarf;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.36, 1.44, 0.53],
        null,
        [0.78, 0.78, 0.82]
      );
    } else if (cosmetics.cowboyId === "vigilVestments") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      // The poncho reads as the chasuble with palms on the shoulders.
      cosmeticParts.poncho.visible = true;
    } else if (cosmetics.cowboyId === "smokingDuelist") {
      cosmeticParts.bandolier.visible = true;
    } else if (cosmetics.cowboyId === "stormPoncho") {
      cosmeticParts.poncho.visible = true;
    } else if (cosmetics.cowboyId === "powderSaint") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.bandolier.visible = true;
      // Dynamite sticks read through the shirt's scorched orange.
      cosmeticParts.bandolier.material = outfit.shirt;
    } else if (cosmetics.cowboyId === "trailMaster") {
      cosmeticParts.poncho.visible = true;
      cosmeticParts.bandolier.visible = true;
    } else if (cosmetics.cowboyId === "palePosse") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.badge.visible = true;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.36, 1.44, 0.53],
        null,
        [0.82, 0.82, 0.86]
      );
    } else if (cosmetics.cowboyId === "silverGhost") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
    } else if (cosmetics.cowboyId === "bullionTycoon") {
      cosmeticParts.coatTailLeft.visible = true;
      cosmeticParts.coatTailRight.visible = true;
      cosmeticParts.bandolier.visible = true;
      cosmeticParts.poncho.visible = true;
      cosmeticParts.badge.visible = true;
      // A deep bronze mantle keeps the head-to-toe gold from flattening into
      // one slab; the poncho defaults to the outfit's brightest cloth.
      cosmeticParts.poncho.material = outfit.leather;
      setCowboyCosmeticTransform(
        cosmeticParts.badge,
        [0.35, 1.44, 0.58],
        null,
        [0.92, 0.92, 0.96]
      );
    }

    parts.hatBrim.material = hat.main;
    parts.hatTop.material = hat.main;
    var hatAccentMaterial = hat.accent || hat.main || mats.playerHat;
    // Hats whose accent is the showpiece (a star, a trophy) keep a plainer band.
    if (cosmeticParts.hatBand) cosmeticParts.hatBand.material = hat.band || hatAccentMaterial;
    if (cosmeticParts.hatAccent) cosmeticParts.hatAccent.material = hatAccentMaterial;
    // The brim mesh carries both the brim roll and the lower crown flare, so each hat
    // gets its own silhouette from a shared cached geometry instead of extra meshes.
    parts.hatBrim.geometry = getCowboyHatBrimGeometry(cosmetics.hatId);
    cosmeticParts.hatBand.visible = true;
    cosmeticParts.hatAccent.visible = false;

    if (cosmetics.hatId === "gamblersBlack") {
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.58, 0], [0, 0, 0], [1.14, 0.86, 1.12]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.18, 0], [0, 0, 0], [1, 1.05, 1]);
    } else if (cosmetics.hatId === "prairieWhite") {
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.74, 0], [0, 0, 0], [1.2, 1.34, 1.18]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.23, 0], [0, 0, 0], [1.08, 1.05, 1.08]);
    } else if (cosmetics.hatId === "marshalStar") {
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.72, 0], [0, 0, 0], [1.1, 1.34, 1.08]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.22, 0], [0, 0, 0], [1.02, 1.05, 1.02]);
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0, 0.04, 0.44], [0, 0, 0], [0.85, 0.7, 1]);
    } else if (cosmetics.hatId === "undertaker") {
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.88, 0], [0, 0, 0], [1.05, 2, 1.03]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.17, 0], [0, 0, 0], [0.96, 1.05, 0.96]);
    } else if (cosmetics.hatId === "railmanCap") {
      // A slightly raised brim and a taller crown keep the cap out of the
      // forehead without making its visor oversized. Preserve the badge's
      // effective height while giving it a little more clearance from the cap.
      setCowboyCosmeticTransform(parts.hatBrim, [0, 2.41, 0], [0, 0, 0], [1, 1, 1]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.58, -0.03], [0, 0, 0], [1.26, 0.86, 1.18]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.11, 0], [0, 0, 0], [1.14, 0.9, 1.1]);
      cosmeticParts.hatAccent.geometry = getClusterGeometry("cowboy-hat-cap-badge-v2", COWBOY_SHAPES.capBadge);
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0, 0.06, 0.47], [0, 0, 0], [0.8, 1.25, 0.9]);
    } else if (cosmetics.hatId === "barrowCrown") {
      // A ring of bone spurs instead of a crown: the Hordeheart's burial mound.
      parts.hatTop.geometry = getClusterGeometry("cowboy-cosmetic-barrow-crown-v1", [
        [0.74, 0.24, 0.62, 0, 0.1, 0],
        [0.13, 0.4, 0.11, 0.26, 0.34, 0.16],
        [0.13, 0.48, 0.11, 0, 0.38, 0.26],
        [0.13, 0.4, 0.11, -0.26, 0.34, 0.16],
        [0.12, 0.32, 0.1, 0.24, 0.3, -0.16],
        [0.12, 0.32, 0.1, -0.24, 0.3, -0.16],
        [0.12, 0.38, 0.1, 0, 0.33, -0.26],
      ]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.5, 0], [0, 0, 0], [1, 1, 1]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.12, 0], [0, 0, 0], [1, 1, 1]);
    } else if (cosmetics.hatId === "surveyorsCap") {
      // The Land-Eater cap mirrors the railman silhouette in survey khaki.
      setCowboyCosmeticTransform(parts.hatBrim, [0, 2.41, 0], [0, 0, 0], [1, 1, 1]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.57, -0.03], [0, 0, 0], [1.24, 0.82, 1.16]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.1, 0], [0, 0, 0], [1.12, 0.88, 1.08]);
      cosmeticParts.hatAccent.geometry = getClusterGeometry("cowboy-hat-cap-badge-v2", COWBOY_SHAPES.capBadge);
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0, 0.05, 0.46], [0, 0, 0], [0.72, 1.1, 0.85]);
    } else if (cosmetics.hatId === "mirrorHalfMask") {
      // No hat at all: a cracked mirror plate covers half the face below the strap.
      parts.hatTop.geometry = getClusterGeometry("cowboy-cosmetic-mirror-mask-v1", [
        [0.48, 0.36, 0.1, 0.14, 0, 0],
        [0.2, 0.28, 0.09, 0.4, -0.03, -0.04],
        [0.17, 0.2, 0.09, -0.1, 0.07, -0.01],
      ]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.06, 0.36], [0.06, 0, 0.05], [1, 1, 1]);
      cosmeticParts.hatBand.visible = false;
    } else if (cosmetics.hatId === "brokenTopper") {
      // The Baron's top hat: a tall tube whose upper half slid off the crack line.
      parts.hatTop.geometry = getClusterGeometry("cowboy-cosmetic-broken-topper-v1", [
        [0.8, 0.66, 0.78, 0, 0.33, 0],
        [0.76, 0.5, 0.74, 0.07, 0.9, -0.04],
        [0.84, 0.12, 0.82, 0.09, 1.19, -0.05],
      ]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.46, 0], [0, 0, -0.05], [1, 1, 1]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.16, 0], [0, 0, 0], [0.98, 1.05, 0.98]);
      // Brass crown teeth ride the crack between the tube halves.
      cosmeticParts.hatAccent.geometry = getClusterGeometry("cowboy-cosmetic-topper-crown-v1", [
        [0.56, 0.09, 0.54, 0, 0, 0],
        [0.1, 0.16, 0.1, 0.22, 0.1, 0.2],
        [0.1, 0.16, 0.1, -0.22, 0.1, 0.2],
        [0.1, 0.16, 0.1, 0.22, 0.1, -0.2],
        [0.1, 0.16, 0.1, -0.22, 0.1, -0.2],
      ]);
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0.03, 0.62, -0.02], [0, 0, 0], [1, 1, 1]);
    } else if (cosmetics.hatId === "fuseHalo") {
      // A smoldering fuse bent into a ring, floating a hand above the hair.
      parts.hatTop.geometry = getSharedGeometry("cowboy-cosmetic-fuse-halo-v1", function () {
        return new THREE.TorusGeometry(0.46, 0.055, 6, 14);
      });
      setCowboyCosmeticTransform(parts.hatTop, [0, 3.02, 0], [Math.PI / 2, 0, 0], [1, 1, 1]);
      cosmeticParts.hatBand.visible = false;
      cosmeticParts.hatAccent.geometry = getSharedGeometry("cowboy-cosmetic-fuse-ember-v1", function () {
        return new THREE.SphereGeometry(0.09, 8, 5);
      });
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0.46, 0, 0], [0, 0, 0], [1, 1, 1]);
    } else if (cosmetics.hatId === "bellCrown") {
      parts.hatTop.geometry = getSharedGeometry("cowboy-cosmetic-bell-crown-v1", function () {
        return new THREE.CylinderGeometry(0.3, 0.48, 0.58, 8, 1, false);
      });
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.64, 0], [0, 0, 0], [1.12, 1.12, 1.12]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.12, 0], [0, 0, 0], [1, 0.95, 1]);
      cosmeticParts.hatAccent.geometry = getSharedGeometry("cowboy-cosmetic-bell-clapper-v1", function () {
        return new THREE.SphereGeometry(0.11, 8, 5);
      });
      cosmeticParts.hatAccent.visible = true;
      // The pulled-down hat leaves no room to hang the clapper, so it rides the bell face.
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0, -0.12, 0.4], [0, 0, 0], [1, 1.15, 1]);
    } else if (cosmetics.hatId === "archbishopMitre") {
      // Stacked, narrowing boxes give the mitre its peak while staying in the
      // blocky vocabulary the rest of the cowboy is built from.
      parts.hatTop.geometry = getClusterGeometry("cowboy-cosmetic-mitre-crown-v1", [
        [0.86, 0.28, 0.64, 0, 0.14, 0],
        [0.76, 0.26, 0.56, 0, 0.40, 0],
        [0.58, 0.24, 0.48, 0, 0.65, 0],
        [0.32, 0.22, 0.40, 0, 0.88, 0],
      ]);
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.42, 0], [0, 0, 0], [1, 1, 1]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.13, 0], [0, 0, 0], [1.02, 1, 1.02]);
      cosmeticParts.hatAccent.geometry = getClusterGeometry("cowboy-cosmetic-mitre-cross-v1", [
        [0.10, 0.36, 0.09, 0, 0, 0],
        [0.26, 0.10, 0.09, 0, 0.06, 0],
      ]);
      cosmeticParts.hatAccent.visible = true;
      setCowboyCosmeticTransform(cosmeticParts.hatAccent, [0, 0.44, 0.30], [0, 0, 0], [1, 1, 1]);
    } else {
      setCowboyCosmeticTransform(parts.hatTop, [0, 2.66, 0], [0, 0, 0], [1.18, 1.19, 1.16]);
      setCowboyCosmeticTransform(cosmeticParts.hatBand, [0, 0.22, 0], [0, 0, 0], [1.06, 1.05, 1.06]);
    }

    animateCowboyTorsoAssembly(group, torsoAnimationPose);
    animateCowboyHeadAssembly(group, headAnimationPose);
    if (activeWeaponVisualId != null) {
      setWeaponMeshes(group, activeWeaponVisualId);
    }
    animateMesh(parts.leftArm, leftArmAnimationPose);
    animateMesh(parts.rightArm, rightArmAnimationPose);

    group.userData.cosmetics = {
      version: 1,
      cowboyId: cosmetics.cowboyId,
      hatId: cosmetics.hatId,
    };
    group.userData.cosmeticSignature = [
      cosmetics.cowboyId,
      cosmetics.hatId,
      parts.hatTop.geometry && (parts.hatTop.geometry.uuid || parts.hatTop.geometry.type),
      outfit.coat && (outfit.coat.name || outfit.coat.uuid),
      hat.main && (hat.main.name || hat.main.uuid),
    ].join("|");
    return group.userData.cosmetics;
  }

  function getCowboyRigidAssemblyDiagnostics(pivot, attachments) {
    if (!pivot || !pivot.userData || !pivot.userData.basePosition) return null;
    var pivotBasePosition = pivot.userData.basePosition;
    var pivotBaseRotation = pivot.userData.baseRotation;
    var maxDistanceError = 0;
    var maxRotationError = 0;
    attachments = attachments || [];
    for (var i = 0; i < attachments.length; i++) {
      var mesh = attachments[i];
      if (
        !mesh ||
        !mesh.userData ||
        !mesh.userData.basePosition ||
        !mesh.userData.baseRotation
      ) continue;
      var base = mesh.userData.basePosition;
      var baseDistance = Math.hypot(
        base.x - pivotBasePosition.x,
        base.y - pivotBasePosition.y,
        base.z - pivotBasePosition.z
      );
      var currentDistance = Math.hypot(
        mesh.position.x - pivot.position.x,
        mesh.position.y - pivot.position.y,
        mesh.position.z - pivot.position.z
      );
      maxDistanceError = Math.max(
        maxDistanceError,
        Math.abs(currentDistance - baseDistance)
      );
      maxRotationError = Math.max(
        maxRotationError,
        Math.abs(
          (mesh.rotation.x - mesh.userData.baseRotation.x) -
          (pivot.rotation.x - pivotBaseRotation.x)
        ),
        Math.abs(
          (mesh.rotation.y - mesh.userData.baseRotation.y) -
          (pivot.rotation.y - pivotBaseRotation.y)
        ),
        Math.abs(
          (mesh.rotation.z - mesh.userData.baseRotation.z) -
          (pivot.rotation.z - pivotBaseRotation.z)
        )
      );
    }
    return {
      attachmentCount: attachments.length,
      maxDistanceError: Number(maxDistanceError.toFixed(6)),
      maxRotationError: Number(maxRotationError.toFixed(6)),
    };
  }

  function getCowboyMeshDepthDiagnostics(mesh) {
    if (!mesh || !mesh.geometry) return null;
    if (!mesh.geometry.boundingBox && typeof mesh.geometry.computeBoundingBox === "function") {
      mesh.geometry.computeBoundingBox();
    }
    var bounds = mesh.geometry.boundingBox;
    if (!bounds) return null;
    return {
      back: Number((mesh.position.z + bounds.min.z * mesh.scale.z).toFixed(4)),
      front: Number((mesh.position.z + bounds.max.z * mesh.scale.z).toFixed(4)),
    };
  }

  function getCowboyWeaponAttachmentDiagnostics(group) {
    if (!group || !group.userData || !group.userData.animParts) return null;
    var parts = group.userData.animParts;
    var rightRig = group.userData.weaponRig;
    var leftRig = group.userData.offhandWeaponRig;
    var activeVisualId = String(group.userData.activeWeaponVisualId || "");
    if (!rightRig || !leftRig || !parts.rightArm || !parts.leftArm) return null;
    group.updateMatrixWorld(true);

    function localPoseError(rig) {
      var basePosition = rig.userData && rig.userData.basePosition;
      var baseRotation = rig.userData && rig.userData.baseRotation;
      return {
        position: basePosition
          ? Number(Math.hypot(
              rig.position.x - basePosition.x,
              rig.position.y - basePosition.y,
              rig.position.z - basePosition.z
            ).toFixed(6))
          : null,
        rotation: baseRotation
          ? Number(Math.hypot(
              rig.rotation.x - baseRotation.x,
              rig.rotation.y - baseRotation.y,
              rig.rotation.z - baseRotation.z
            ).toFixed(6))
          : null,
      };
    }

    function cuffToPalmMetrics(arm, hand, armed) {
      if (!arm || !hand) return null;
      var cuffLocal = armed
        ? new THREE.Vector3(0, -0.39, 0.56)
        : new THREE.Vector3(0, -0.88, 0.05);
      var cuffWorld = arm.localToWorld(cuffLocal.clone());
      var palmWorld = new THREE.Vector3();
      hand.getWorldPosition(palmWorld);
      var palmLocal = arm.worldToLocal(palmWorld.clone());
      var offset = palmLocal.sub(cuffLocal);
      if (!hand.geometry.boundingBox && typeof hand.geometry.computeBoundingBox === "function") {
        hand.geometry.computeBoundingBox();
      }
      var bounds = hand.geometry.boundingBox;
      var palmWidth = bounds
        ? Math.abs(bounds.max.x - bounds.min.x) * Math.abs(hand.scale.x)
        : 0;
      var palmDepth = bounds
        ? Math.abs(bounds.max.z - bounds.min.z) * Math.abs(hand.scale.z)
        : 0;
      var cuffWidth = armed ? 0.34 : 0.34;
      var cuffDepth = armed ? 0.12 : 0.36;
      return {
        distance: Number(cuffWorld.distanceTo(palmWorld).toFixed(6)),
        offset: {
          x: Number(offset.x.toFixed(6)),
          y: Number(offset.y.toFixed(6)),
          z: Number(offset.z.toFixed(6)),
        },
        // Top-down overflow catches a palm that is still technically attached
        // but visibly sticks out beside the sleeve.
        lateralOverflow: Number(Math.max(
          0,
          Math.abs(offset.x) + palmWidth * 0.5 - cuffWidth * 0.5
        ).toFixed(6)),
        sleeveContactDepth: Number(Math.max(
          0,
          cuffDepth * 0.5 + palmDepth * 0.5 - Math.abs(offset.z)
        ).toFixed(6)),
      };
    }

    var rightPoseError = localPoseError(rightRig);
    var leftPoseError = localPoseError(leftRig);
    var dualActive = activeVisualId === "dualRevolvers";
    var rightGrip = cuffToPalmMetrics(parts.rightArm, parts.rightHand, true);
    var leftGrip = cuffToPalmMetrics(
      parts.leftArm,
      parts.leftHand,
      dualActive
    );
    return {
      activeVisualId: activeVisualId,
      right: {
        rigParentIsArm: rightRig.parent === parts.rightArm,
        handParentIsRig: !!parts.rightHand && parts.rightHand.parent === rightRig,
        visible: !!rightRig.visible,
        localPositionError: rightPoseError.position,
        localRotationError: rightPoseError.rotation,
        cuffToPalmDistance: rightGrip ? rightGrip.distance : null,
        cuffToPalmOffset: rightGrip ? rightGrip.offset : null,
        lateralOverflow: rightGrip ? rightGrip.lateralOverflow : null,
        sleeveContactDepth: rightGrip ? rightGrip.sleeveContactDepth : null,
      },
      left: {
        rigParentIsArm: leftRig.parent === parts.leftArm,
        handParentIsRig: !!parts.leftHand && parts.leftHand.parent === leftRig,
        visible: !!leftRig.visible,
        armedGeometry: !!(
          group.userData.cowboyArmGeometries &&
          parts.leftArm.geometry === group.userData.cowboyArmGeometries.leftArmed
        ),
        localPositionError: leftPoseError.position,
        localRotationError: leftPoseError.rotation,
        cuffToPalmDistance: leftGrip ? leftGrip.distance : null,
        cuffToPalmOffset: leftGrip ? leftGrip.offset : null,
        lateralOverflow: leftGrip ? leftGrip.lateralOverflow : null,
        sleeveContactDepth: leftGrip ? leftGrip.sleeveContactDepth : null,
      },
      poses: {
        leftArmRotationX: Number(parts.leftArm.rotation.x.toFixed(6)),
        rightArmRotationX: Number(parts.rightArm.rotation.x.toFixed(6)),
      },
    };
  }

  function getCowboyCosmeticDiagnostics(group) {
    if (!group || !group.userData || !group.userData.animParts) return null;
    var parts = group.userData.animParts;
    var cosmeticParts = group.userData.cosmeticParts || {};
    var visibleMeshCount = 0;
    var visibleMeshesMissingMaterial = 0;
    var visibleMeshesMissingGeometry = 0;
    group.traverse(function (object) {
      if (!object || !object.isMesh || !object.visible) return;
      visibleMeshCount += 1;
      if (!object.geometry) visibleMeshesMissingGeometry += 1;
      if (
        !object.material ||
        (Array.isArray(object.material) && object.material.some(function (entry) { return !entry; }))
      ) {
        visibleMeshesMissingMaterial += 1;
      }
    });
    return {
      cosmetics: serializeCowboyCosmetics(group.userData.cosmetics),
      signature: String(group.userData.cosmeticSignature || ""),
      visibleMeshCount: visibleMeshCount,
      visibleMeshesMissingMaterial: visibleMeshesMissingMaterial,
      visibleMeshesMissingGeometry: visibleMeshesMissingGeometry,
      hatGeometry: parts.hatTop && parts.hatTop.geometry
        ? String(parts.hatTop.geometry.type || "")
        : "",
      materials: {
        coat: parts.torso && parts.torso.material
          ? String(parts.torso.material.name || parts.torso.material.uuid || "")
          : "",
        hat: parts.hatTop && parts.hatTop.material
          ? String(parts.hatTop.material.name || parts.hatTop.material.uuid || "")
          : "",
      },
      visibleAccessories: Object.keys(cosmeticParts).filter(function (key) {
        return cosmeticParts[key] && cosmeticParts[key].visible;
      }),
      hatTopY: parts.hatTop ? Number(parts.hatTop.position.y.toFixed(4)) : 0,
      transforms: {
        shirtZ: parts.shirt ? Number(parts.shirt.position.z.toFixed(4)) : 0,
        scarfZ: parts.scarf ? Number(parts.scarf.position.z.toFixed(4)) : 0,
        beltY: parts.belt ? Number(parts.belt.position.y.toFixed(4)) : 0,
        beltZ: parts.belt ? Number(parts.belt.position.z.toFixed(4)) : 0,
        hatBrimY: parts.hatBrim ? Number(parts.hatBrim.position.y.toFixed(4)) : 0,
        hatTopY: parts.hatTop ? Number(parts.hatTop.position.y.toFixed(4)) : 0,
        hatTopScale: parts.hatTop
          ? [
              Number(parts.hatTop.scale.x.toFixed(4)),
              Number(parts.hatTop.scale.y.toFixed(4)),
              Number(parts.hatTop.scale.z.toFixed(4)),
            ]
          : [0, 0, 0],
      },
      assemblies: {
        torso: getCowboyRigidAssemblyDiagnostics(
          parts.torso,
          group.userData.cowboyTorsoAttachments
        ),
        headwear: getCowboyRigidAssemblyDiagnostics(
          parts.head,
          group.userData.cowboyHeadwearAttachments
        ),
      },
      weaponAttachments: getCowboyWeaponAttachmentDiagnostics(group),
      depth: {
        torso: getCowboyMeshDepthDiagnostics(parts.torso),
        shirt: getCowboyMeshDepthDiagnostics(parts.shirt),
        scarf: getCowboyMeshDepthDiagnostics(parts.scarf),
        belt: getCowboyMeshDepthDiagnostics(parts.belt),
        coatTailLeft: getCowboyMeshDepthDiagnostics(cosmeticParts.coatTailLeft),
        bandolier: getCowboyMeshDepthDiagnostics(cosmeticParts.bandolier),
        badge: getCowboyMeshDepthDiagnostics(cosmeticParts.badge),
        poncho: getCowboyMeshDepthDiagnostics(cosmeticParts.poncho),
      },
    };
  }

  // Five-pointed star built from boxes so badges read as a real star silhouette.
  function buildStarBoxes(radius, depth, pointLength, pointWidth) {
    var boxes = [[radius * 1.05, radius * 1.05, depth, 0, 0, 0]];
    for (var point = 0; point < 5; point++) {
      var angle = point * Math.PI * 0.4;
      boxes.push([
        pointWidth,
        pointLength,
        depth * 0.85,
        Math.sin(angle) * radius * 0.78,
        Math.cos(angle) * radius * 0.78,
        0,
        0,
        0,
        -angle,
      ]);
    }
    return boxes;
  }

