  function getZombieConfig(type) {
    return {
      walker: { hp: 2, speed: 2.35, radius: 0.68, damage: 13, scale: 1, score: 100, xp: 4, color: mats.zombieSkin },
      runner: { hp: 1, speed: 3.85, radius: 0.58, damage: 11, scale: 0.86, score: 140, xp: 5, color: mats.zombieSkin },
      fastZombie: { hp: 2, speed: getFastZombieSpeed(), radius: 0.56, damage: 12, scale: 0.95, score: 220, xp: 8, color: mats.fastZombieSkin, fast: true },
      brute: { hp: 5, speed: 1.85, radius: 0.93, damage: 24, scale: 1.28, score: 280, xp: 12, color: mats.zombieSkin },
      spitter: { hp: 4, speed: 1.92, radius: 0.62, damage: 14, scale: 1.0, score: 320, xp: 16, color: mats.zombieAcidSkin, tall: true },
      armoredMiner: { hp: 9, speed: 1.96, radius: 0.82, damage: 19, scale: 1.08, score: 380, xp: 18, color: mats.zombieSkin, miner: true },
      gravePreacher: { hp: 7, speed: 1.58, radius: 0.74, damage: 13, scale: 1.06, score: 640, xp: 32, color: mats.zombieSkin, preacher: true },
    }[type] || {
      hp: 2,
      speed: 2.35,
      radius: 0.68,
      damage: 13,
      scale: 1,
      score: 100,
      xp: 4,
      color: mats.zombieSkin,
    };
  }

  function getFastZombieSpeed() {
    var playerSpeed = state.player && state.player.speed ? state.player.speed : BASE_PLAYER_SPEED;
    return playerSpeed * FAST_ZOMBIE_SPEED_MULTIPLIER + FAST_ZOMBIE_SPEED_BONUS;
  }

  function resolveZombieBaseSpeed(type, config) {
    return type === "fastZombie" || (config && config.fast) ? getFastZombieSpeed() : config.speed;
  }

  function refreshZombieSpeed(enemy) {
    if (!enemy) return 0;
    if (enemy.type === "fastZombie") enemy.speed = getFastZombieSpeed();
    return enemy.speed;
  }

  function makeZombie(type) {
    return createZombieEntity(type, false);
  }

  function addEnemyAccessoryBox(parent, w, h, d, mat, x, y, z, castShadow) {
    var mesh = new THREE.Mesh(
      getSharedGeometry("enemy-accessory-unit-box", function () { return new THREE.BoxGeometry(1, 1, 1); }),
      mat
    );
    mesh.position.set(x || 0, y || 0, z || 0);
    mesh.scale.set(w, h, d);
    mesh.castShadow = castShadow !== false;
    mesh.receiveShadow = true;
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    parent.add(mesh);
    return rememberBase(mesh);
  }

  function addEnemyAccessoryMesh(parent, key, geometryFactory, mat, x, y, z, castShadow) {
    var mesh = new THREE.Mesh(getSharedGeometry(key, geometryFactory), mat);
    mesh.position.set(x || 0, y || 0, z || 0);
    mesh.castShadow = castShadow !== false;
    mesh.receiveShadow = true;
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    parent.add(mesh);
    return rememberBase(mesh);
  }

  // Ghost Train ---------------------------------------------------------

  function createGhostTrainSteamPuffTexture() {
    var canvas = document.createElement("canvas");
    canvas.width = 64;
    canvas.height = 64;
    var context = canvas.getContext("2d");

    function paintSteamBlob(x, y, radius, opacity) {
      var gradient = context.createRadialGradient(
        x - radius * 0.14,
        y - radius * 0.18,
        radius * 0.08,
        x,
        y,
        radius
      );
      gradient.addColorStop(0, "rgba(255,255,255," + opacity + ")");
      gradient.addColorStop(0.38, "rgba(255,255,255," + (opacity * 0.82) + ")");
      gradient.addColorStop(0.7, "rgba(238,255,251," + (opacity * 0.34) + ")");
      gradient.addColorStop(1, "rgba(225,255,248,0)");
      context.fillStyle = gradient;
      context.fillRect(x - radius, y - radius, radius * 2, radius * 2);
    }

    context.clearRect(0, 0, 64, 64);
    paintSteamBlob(32, 35, 27, 0.82);
    paintSteamBlob(20, 37, 16, 0.58);
    paintSteamBlob(45, 37, 17, 0.62);
    paintSteamBlob(27, 23, 17, 0.58);
    paintSteamBlob(40, 24, 15, 0.5);
    var texture = new THREE.CanvasTexture(canvas);
    texture.name = "Ghost Train soft steam puff";
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.generateMipmaps = true;
    return texture;
  }

  function configureGhostTrainTunnelDissolveMaterial(material, cacheKey) {
    if (!material) return material;
    material.userData.ghostTrainTunnelDissolveShaderInjected = false;
    material.onBeforeCompile = function (shader) {
      if (
        shader.vertexShader.indexOf("#include <begin_vertex>") === -1 ||
        shader.fragmentShader.indexOf("#include <color_fragment>") === -1
      ) {
        material.userData.ghostTrainTunnelDissolveShaderInjected = false;
        return;
      }
      shader.uniforms.ghostTrainTunnelDissolveEnabled = ghostTrainTunnelDissolveUniforms.enabled;
      shader.uniforms.ghostTrainTunnelDissolvePlane = ghostTrainTunnelDissolveUniforms.plane;
      shader.uniforms.ghostTrainTunnelDissolveDirection = ghostTrainTunnelDissolveUniforms.direction;
      shader.uniforms.ghostTrainTunnelDissolveWidth = ghostTrainTunnelDissolveUniforms.width;
      shader.uniforms.ghostTrainTunnelDissolveTime = ghostTrainTunnelDissolveUniforms.time;
      shader.vertexShader = "varying vec3 vGhostTrainTunnelWorldPosition;\n" + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace(
        "#include <begin_vertex>",
        "#include <begin_vertex>\nvGhostTrainTunnelWorldPosition = (modelMatrix * vec4(transformed, 1.0)).xyz;"
      );
      shader.fragmentShader = [
        "uniform float ghostTrainTunnelDissolveEnabled;",
        "uniform vec4 ghostTrainTunnelDissolvePlane;",
        "uniform float ghostTrainTunnelDissolveDirection;",
        "uniform float ghostTrainTunnelDissolveWidth;",
        "uniform float ghostTrainTunnelDissolveTime;",
        "varying vec3 vGhostTrainTunnelWorldPosition;",
        shader.fragmentShader,
      ].join("\n");
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <color_fragment>",
        [
          "#include <color_fragment>",
          "if (ghostTrainTunnelDissolveEnabled > 0.5) {",
          "  float ghostTrainTunnelSignedDistance = (dot(ghostTrainTunnelDissolvePlane.xyz, vGhostTrainTunnelWorldPosition) + ghostTrainTunnelDissolvePlane.w) * ghostTrainTunnelDissolveDirection;",
          "  float ghostTrainTunnelWidth = max(0.05, ghostTrainTunnelDissolveWidth);",
          "  float ghostTrainTunnelVisibility = clamp(0.5 - ghostTrainTunnelSignedDistance / ghostTrainTunnelWidth, 0.0, 1.0);",
          "  vec3 ghostTrainTunnelCell = floor(vGhostTrainTunnelWorldPosition * 5.5);",
          "  float ghostTrainTunnelGrain = fract(sin(dot(ghostTrainTunnelCell, vec3(12.9898, 78.233, 37.719)) + ghostTrainTunnelDissolveTime * 2.1) * 43758.5453);",
          "  float ghostTrainTunnelEdge = 1.0 - smoothstep(0.0, ghostTrainTunnelWidth * 0.62, abs(ghostTrainTunnelSignedDistance));",
          "  diffuseColor.rgb += vec3(0.10, 0.95, 0.72) * ghostTrainTunnelEdge * (0.20 + ghostTrainTunnelGrain * 0.16);",
          "  if (ghostTrainTunnelGrain > ghostTrainTunnelVisibility) discard;",
          "  diffuseColor.a *= 0.68 + ghostTrainTunnelVisibility * 0.32;",
          "}",
        ].join("\n")
      );
      material.userData.ghostTrainTunnelDissolveShaderInjected = true;
    };
    material.customProgramCacheKey = function () { return "ghost-train-tunnel-dissolve-" + cacheKey + "-v1"; };
    material.needsUpdate = true;
    return material;
  }

