  function registerGhostTrainMaterialMesh(mesh, parts, solidMaterial, spectralMaterial) {
    if (!mesh) return mesh;
    mesh.userData.ghostTrainSolidMaterial = solidMaterial || mesh.material;
    mesh.userData.ghostTrainSpectralMaterial = spectralMaterial || mats.ghostTrainSpectral;
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    mesh.userData.noDebris = true;
    if (parts && parts.materialMeshes) parts.materialMeshes.push(mesh);
    return mesh;
  }

  function addGhostTrainBox(parent, parts, w, h, d, mat, x, y, z, spectralMat) {
    var mesh = addEnemyAccessoryBox(parent, w, h, d, mat, x, y, z, true);
    return registerGhostTrainMaterialMesh(mesh, parts, mat, spectralMat);
  }

  function addGhostTrainMesh(parent, parts, key, geometryFactory, mat, x, y, z, spectralMat) {
    var mesh = addEnemyAccessoryMesh(parent, key, geometryFactory, mat, x, y, z, true);
    return registerGhostTrainMaterialMesh(mesh, parts, mat, spectralMat);
  }

  var ghostTrainStaticBatchParentInverseScratch = new THREE.Matrix4();
  var ghostTrainStaticBatchMatrixScratch = new THREE.Matrix4();

  function markGhostTrainStaticBatchExcluded(root) {
    if (!root || typeof root.traverse !== "function") return;
    root.traverse(function (object) {
      object.userData = object.userData || {};
      object.userData.ghostTrainStaticBatchExcluded = true;
    });
  }

  function markGhostTrainDynamicBatchExclusions(parts) {
    if (!parts) return;
    var dynamicRoots = [];
    dynamicRoots = dynamicRoots.concat(parts.wheels || []);
    dynamicRoots = dynamicRoots.concat((parts.cannons || []).map(function (cannon) {
      return cannon && cannon.pivot;
    }).filter(Boolean));
    dynamicRoots = dynamicRoots.concat(parts.rods || []);
    dynamicRoots.push(parts.targetMarker, parts.rearLantern, parts.furnace);
    for (var dynamicIndex = 0; dynamicIndex < dynamicRoots.length; dynamicIndex++) {
      markGhostTrainStaticBatchExcluded(dynamicRoots[dynamicIndex]);
    }
  }

  function createGhostTrainStaticVisualBatch(group, parts, spec, batchIndex) {
    var sources = spec && spec.sources || [];
    if (
      !group || !parts || sources.length < 2 ||
      typeof THREE.BatchedMesh !== "function"
    ) return null;
    var vertexCapacity = 0;
    var indexCapacity = 0;
    var indexed = null;
    for (var sourceIndex = 0; sourceIndex < sources.length; sourceIndex++) {
      var sourceGeometry = sources[sourceIndex] && sources[sourceIndex].geometry;
      if (!sourceGeometry || !sourceGeometry.attributes || !sourceGeometry.attributes.position) return null;
      var sourceIndexed = !!sourceGeometry.index;
      if (indexed == null) indexed = sourceIndexed;
      if (indexed !== sourceIndexed) return null;
      vertexCapacity += sourceGeometry.attributes.position.count;
      if (sourceIndexed) indexCapacity += sourceGeometry.index.count;
    }
    if (!vertexCapacity || (indexed && !indexCapacity)) return null;

    var batch = null;
    try {
      batch = new THREE.BatchedMesh(
        sources.length,
        vertexCapacity,
        indexCapacity,
        spec.solidMaterial
      );
      batch.name = "Ghost Train static visual batch " + batchIndex;
      batch.castShadow = false;
      batch.receiveShadow = !!spec.receiveShadow;
      batch.frustumCulled = false;
      batch.perObjectFrustumCulled = true;
      // The same batch becomes transparent when the train turns spectral.
      // Per-object sorting preserves the authored translucent overlap.
      batch.sortObjects = true;
      batch.renderOrder = spec.renderOrder;
      batch.userData.disposeGeometry = false;
      batch.userData.disposeMaterial = false;
      batch.userData.noDebris = true;
      batch.userData.ghostTrainStaticVisualBatch = true;
      batch.userData.ghostTrainBatchSources = sources;
      batch.userData.ghostTrainBatchSourceCount = sources.length;
      group.add(batch);

      // Visual prewarm is started near the top of this monolithic script,
      // before later variable initializers execute. Lazily initialize these
      // reusable matrices for that bootstrap path.
      if (!ghostTrainStaticBatchParentInverseScratch) {
        ghostTrainStaticBatchParentInverseScratch = new THREE.Matrix4();
      }
      if (!ghostTrainStaticBatchMatrixScratch) {
        ghostTrainStaticBatchMatrixScratch = new THREE.Matrix4();
      }
      group.updateMatrixWorld(true);
      ghostTrainStaticBatchParentInverseScratch.copy(group.matrixWorld).invert();
      for (var instanceIndex = 0; instanceIndex < sources.length; instanceIndex++) {
        var source = sources[instanceIndex];
        var instanceId = batch.addGeometry(source.geometry);
        ghostTrainStaticBatchMatrixScratch.multiplyMatrices(
          ghostTrainStaticBatchParentInverseScratch,
          source.matrixWorld
        );
        batch.setMatrixAt(instanceId, ghostTrainStaticBatchMatrixScratch);
        source.userData.ghostTrainStaticVisualBatch = batch;
        source.userData.ghostTrainStaticVisualBatchInstanceId = instanceId;
        source.userData.ghostTrainStaticVisualSourceVisible = source.visible !== false;
        // Keep the authored source as a stable animation/debug proxy. Only its
        // byte-identical batched copy is submitted to the renderer.
        source.visible = false;
      }
      registerGhostTrainMaterialMesh(
        batch,
        parts,
        spec.solidMaterial,
        spec.spectralMaterial
      );
      return batch;
    } catch (error) {
      parts.staticBatchError = String(error && error.message || error || "batch-create-failed");
      if (batch && batch.parent) batch.parent.remove(batch);
      if (batch && typeof batch.dispose === "function") batch.dispose();
      for (var restoreIndex = 0; restoreIndex < sources.length; restoreIndex++) {
        var restoreSource = sources[restoreIndex];
        if (
          !restoreSource || !restoreSource.userData ||
          restoreSource.userData.ghostTrainStaticVisualBatch !== batch
        ) continue;
        restoreSource.visible = restoreSource.userData.ghostTrainStaticVisualSourceVisible !== false;
        delete restoreSource.userData.ghostTrainStaticVisualBatch;
        delete restoreSource.userData.ghostTrainStaticVisualBatchInstanceId;
        delete restoreSource.userData.ghostTrainStaticVisualSourceVisible;
      }
      return null;
    }
  }

  function createGhostTrainStaticVisualBatches(group) {
    var parts = group && group.userData && group.userData.ghostTrainParts;
    if (!parts || typeof THREE.BatchedMesh !== "function") return false;
    markGhostTrainDynamicBatchExclusions(parts);
    var specsByState = Object.create(null);
    group.traverse(function (object) {
      if (
        !object || !object.isMesh || object.isInstancedMesh || object.isBatchedMesh ||
        !object.geometry || !object.material || object.visible === false ||
        object.userData.ghostTrainStaticBatchExcluded ||
        !object.userData.ghostTrainSolidMaterial
      ) return;
      var solidMaterial = object.userData.ghostTrainSolidMaterial;
      var spectralMaterial = object.userData.ghostTrainSpectralMaterial;
      var indexed = object.geometry.index ? "indexed" : "plain";
      var stateKey = solidMaterial.uuid + ":" + spectralMaterial.uuid + ":" +
        (object.receiveShadow ? "receive" : "flat") + ":" +
        String(Number(object.renderOrder) || 0) + ":" + indexed;
      if (!specsByState[stateKey]) {
        specsByState[stateKey] = {
          solidMaterial: solidMaterial,
          spectralMaterial: spectralMaterial,
          receiveShadow: !!object.receiveShadow,
          renderOrder: Number(object.renderOrder) || 0,
          sources: [],
        };
      }
      specsByState[stateKey].sources.push(object);
    });
    parts.staticVisualBatches = [];
    parts.staticBatchSourceCount = 0;
    Object.keys(specsByState).forEach(function (stateKey, batchIndex) {
      var spec = specsByState[stateKey];
      var batch = createGhostTrainStaticVisualBatch(group, parts, spec, batchIndex);
      if (!batch) return;
      parts.staticVisualBatches.push(batch);
      parts.staticBatchSourceCount += spec.sources.length;
    });
    group.userData.ghostTrainStaticBatched = parts.staticVisualBatches.length > 0;
    return group.userData.ghostTrainStaticBatched;
  }

  function addGhostTrainShadowProxyMesh(parent, geometry, x, y, z, sx, sy, sz, rotationX) {
    var mesh = new THREE.Mesh(geometry, mats.ghostTrainShadowProxy);
    mesh.position.set(x, y, z);
    mesh.scale.set(sx, sy, sz);
    if (rotationX) mesh.rotation.x = rotationX;
    mesh.castShadow = true;
    mesh.receiveShadow = false;
    mesh.layers.set(GHOST_TRAIN_SHADOW_PROXY_LAYER);
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    mesh.userData.noDebris = true;
    mesh.userData.ghostTrainShadowProxy = true;
    parent.add(mesh);
    return mesh;
  }

  function createGhostTrainShadowProxy(group, parts, locomotive) {
    if (!group || !parts) return null;
    var proxyRoot = new THREE.Group();
    proxyRoot.name = locomotive
      ? "Ghost Train locomotive shadow hull"
      : "Ghost Train wagon shadow hull";
    proxyRoot.visible = false;
    proxyRoot.userData.ghostTrainShadowProxyRoot = true;
    group.add(proxyRoot);
    var unitBox = getSharedGeometry(
      "ghost-train-shadow-proxy-unit-box",
      function () { return new THREE.BoxGeometry(1, 1, 1); }
    );
    var unitCylinder = getSharedGeometry(
      "ghost-train-shadow-proxy-unit-cylinder",
      function () { return new THREE.CylinderGeometry(1, 1, 1, 10); }
    );
    var meshes = [];
    if (locomotive) {
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitBox, 0, 1.02, 0.25, 3.82, 0.72, 6.35, 0));
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitCylinder, 0, 2.18, 0.88, 1.18, 4.28, 1.18, Math.PI / 2));
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitBox, 0, 2.45, -1.75, 3.55, 2.65, 2.48, 0));
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitCylinder, 0, 4.08, GHOST_TRAIN_STACK_FORWARD_OFFSET, 0.58, 2.16, 0.58, 0));
    } else {
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitBox, 0, 0.98, 0, 3.72, 0.72, 6.22, 0));
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitBox, 0, 2.08, 0, 3.18, 2.32, 5.62, 0));
      meshes.push(addGhostTrainShadowProxyMesh(proxyRoot, unitBox, 0, 3.32, 0, 3.58, 0.48, 6.18, 0));
    }
    parts.shadowProxyRoot = proxyRoot;
    parts.shadowProxyMeshes = meshes;
    // Authored detail remains visible and receives shadows; only the compact
    // proxy hull is submitted to the shadow camera.
    for (var detailIndex = 0; detailIndex < parts.materialMeshes.length; detailIndex++) {
      parts.materialMeshes[detailIndex].castShadow = false;
    }
    return proxyRoot;
  }

