      active: true,
      attached: true,
      detaching: false,
      vulnerableTarget: false,
      hp: hp,
      maxHp: hp,
      x: 0,
      z: 0,
      oldX: 0,
      oldZ: 0,
      facingAngle: 0,
      pathDistance: 0,
