    var fadeDelay = getGhostTrainTrackFadeDelay(encounter);
    var tailDistance = engineDistance - getGhostTrainTrackTailLength(encounter);
    var minDistance = tailDistance - getGhostTrainSpeed(encounter) * fadeDelay - 4;
    var maxDistance = engineDistance + getGhostTrainPreviewDistance(encounter) + 3;
