    towerRoof.rotation.y = Math.PI / 4;
    addEnemyAccessoryBox(tower, 0.18, 1.38, 0.18, mats.bellRingerIron, 0, 8.84, 0);
    addEnemyAccessoryBox(tower, 1.0, 0.18, 0.18, mats.bellRingerIron, 0, 8.77, 0);
    var bellAuraMaterial = mats.bellSpectralGlow.clone();
