      circleFill.position.y = 0.043;
      circleFill.userData.disposeGeometry = true;
      circleFill.userData.disposeMaterial = true;
      var circleEdge = new THREE.Mesh(new THREE.RingGeometry(0.9, 1.02, 40, 1), edgeMaterial);
      circleEdge.rotation.x = -Math.PI / 2;
      circleEdge.position.y = 0.058;
      circleEdge.userData.disposeGeometry = true;
      circleEdge.userData.disposeMaterial = true;
