    var maxHp = getHordeheartBodyMaxHp(sizeClass);
    var emergenceActive = !!(spawnSpec && spawnSpec.continuous);
    var sourceX = spawnSpec && Number.isFinite(Number(spawnSpec.sourceX)) ? Number(spawnSpec.sourceX) : x;
    var sourceZ = spawnSpec && Number.isFinite(Number(spawnSpec.sourceZ)) ? Number(spawnSpec.sourceZ) : z;
