      fragmentId: String(spawnSpec && spawnSpec.fragmentId || (sizeClass === "whole" ? "root" : sizeClass + "-" + index)),
      parentFragmentId: String(spawnSpec && spawnSpec.parentFragmentId || (sizeClass === "whole" ? "flesh-debris" : "")),
      parentBodyIndex: spawnSpec && Number.isFinite(Number(spawnSpec.parentBodyIndex)) ? Number(spawnSpec.parentBodyIndex) : -1,
      parentNetworkId: String(spawnSpec && spawnSpec.parentNetworkId || ""),
      childOrdinal: spawnSpec && Number.isFinite(Number(spawnSpec.childOrdinal)) ? Number(spawnSpec.childOrdinal) : 0,
      targetSplitIndex: spawnSpec && Number.isFinite(Number(spawnSpec.targetSplitIndex)) ? Number(spawnSpec.targetSplitIndex) : index,
