      sourceApi: String(spawnSpec && spawnSpec.sourceApi || (sizeClass === "whole" ? "fleshConvergence" : "phaseLayoutFallback")),
      usedModelAnchor: !!(spawnSpec && spawnSpec.usedModelAnchor),
