      sourceY: sourceY,
      sourceZ: sourceZ,
      sourceQuaternion: sourceQuaternion || { x: 0, y: 0, z: 0, w: 1 },
      sourceScale: sourceScale || baseGroupScale,
      spawnContinuityError: Math.hypot(x - sourceX, z - sourceZ),
      active: true,
      downed: false,
      x: x,
      z: z,
      targetX: x,
      targetZ: z,
      networkHasTarget: false,
      networkPreviousTargetX: x,
      networkPreviousTargetZ: z,
      networkPreviousTargetAngle: 0,
      networkPreviousGaitPhase: getHordeheartInitialGaitPhase(sizeClass, index),
      networkTargetSampleTime: 0,
      networkPreviousSampleTime: 0,
      networkTargetLocalTime: 0,
      networkVelocityX: 0,
      networkVelocityZ: 0,
      networkAngularVelocity: 0,
      networkTargetAngle: 0,
      networkTargetGaitPhase: getHordeheartInitialGaitPhase(sizeClass, index),
      networkGaitVelocity: 0,
      networkTargetMoving: false,
      facingAngle: spawnSpec && Number.isFinite(Number(spawnSpec.facingAngle)) ? Number(spawnSpec.facingAngle) : 0,
      radius: HORDEHEART_BODY_RADII[sizeClass],
      hp: maxHp,
      maxHp: maxHp,
      damage: 20,
      speed: getHordeheartBodySpeed(sizeClass),
      score: 0,
      xp: 0,
      group: group,
      baseGroupScale: baseGroupScale,
      emergenceActive: emergenceActive,
      emergenceTimer: 0,
      emergenceDuration: HORDEHEART_EMERGENCE_DURATION,
      emergenceProgress: emergenceActive ? 0 : 1,
      emergenceStartX: sourceX,
      emergenceStartY: sourceY,
      emergenceStartZ: sourceZ,
      emergenceTargetX: spawnSpec && Number.isFinite(Number(spawnSpec.targetX)) ? Number(spawnSpec.targetX) : x,
      emergenceTargetZ: spawnSpec && Number.isFinite(Number(spawnSpec.targetZ)) ? Number(spawnSpec.targetZ) : z,
      networkEmergenceTargetProgress: emergenceActive ? 0 : 1,
      networkEmergenceTargetLocalTime: 0,
      action: "idle",
      actionTimer: 0,
      actionDuration: 0,
      attackCooldown: 1.4 + index * 0.2,
      moveAmount: 0,
      gaitPhase: getHordeheartInitialGaitPhase(sizeClass, index),
      pullDrive: 0,
      pullSpeedMultiplier: isHordeheartPullingFragment(sizeClass)
