      navGoalStorage: { x: 0, z: 0, holdUntil: 0, expires: 0 },
      navPath: null,
      navPathIndex: 0,
      navPathTargetX: x,
      navPathTargetZ: z,
      navPathExpires: 0,
      navBlockerType: "",
      steerX: Math.sin(spawnSpec && Number.isFinite(Number(spawnSpec.facingAngle)) ? Number(spawnSpec.facingAngle) : 0),
      steerZ: Math.cos(spawnSpec && Number.isFinite(Number(spawnSpec.facingAngle)) ? Number(spawnSpec.facingAngle) : 0),
      avoidSide: index % 2 ? -1 : 1,
      stuckTimer: 0,
      attackFacingAngle: null,
      hitPulse: 0,
      fireSlowTimer: 0,
      marshalStunTimer: 0,
      marshalFearTimer: 0,
      marshalMarkTimer: 0,
      marshalBountyTimer: 0,
      deathTimer: 0,
      deathStartedAt: 0,
      deathDuration: 0,
