      sourceBossWave: Math.max(1, Math.floor(Number(encounter.sourceBossWave) || 1)),
      dueBossWave: Math.max(1, Math.floor(Number(encounter.dueBossWave) || 1)),
      stolenXp: Math.max(0, Math.round(Number(encounter.stolenXp) || 0)),
      transformSeq: Math.max(0, Math.floor(Number(encounter.transformSequence) || 0)),
      deathSeq: Math.max(0, Math.floor(Number(encounter.deathSequence) || 0)),
