    encounter.engineDistance = hardReset
      ? encounter.replicaNetworkEngineDistance
      : findClosestGhostTrainTrackDistance(densePoints, visualX, visualZ, encounter.replicaNetworkEngineDistance, 38);
    var targetRevealDistance = densePoints[densePoints.length - 1].d;
    var revealDistance = targetRevealDistance;
