    if (!(sampleDelta > 0.0001)) sampleDelta = MULTIPLAYER_SNAPSHOT_INTERVAL;
    var velocityX = created ? 0 : (target.x - previousTargetX) / sampleDelta;
    var velocityZ = created ? 0 : (target.z - previousTargetZ) / sampleDelta;
    var velocityLength = Math.hypot(velocityX, velocityZ);
    if (velocityLength > 32) {
      velocityX = velocityX / velocityLength * 32;
      velocityZ = velocityZ / velocityLength * 32;
    }
