    detached.networkPreviousTargetX = created ? target.x : previousTargetX;
    detached.networkPreviousTargetZ = created ? target.z : previousTargetZ;
    detached.networkPreviousTargetAngle = created ? target.angle : previousTargetAngle;
    detached.networkPreviousTargetPathDistance = created ? target.pathDistance : previousTargetPathDistance;
    detached.networkPreviousSampleTime = created ? sampleTime : previousSampleTime;
    detached.networkTargetX = target.x;
    detached.networkTargetZ = target.z;
    detached.networkTargetAngle = target.angle;
    detached.networkTargetPathDistance = target.pathDistance;
    detached.networkTargetSampleTime = sampleTime;
    detached.networkTargetLocalTime = state.time;
    detached.networkVelocityX = velocityX;
    detached.networkVelocityZ = velocityZ;
