    segment.z += (desiredZ - segment.z) * alpha;
    segment.facingAngle += normalizeGhostTrainAngle(desiredAngle - segment.facingAngle) * alpha;
    detached.pathDistance += (desiredPathDistance - detached.pathDistance) * alpha;
    segment.pathDistance = detached.pathDistance;
