        segment: segment,
        segmentIndex: segmentIndex,
        pathDistance: encounter.engineDistance,
        speed: 0,
        timer: GHOST_TRAIN_DETACH_TIME,
        duration: GHOST_TRAIN_DETACH_TIME,
