    var previousActionSequence = Math.max(0, encounter.actionSequence || 0);
    var previousRouteSequence = Math.max(0, encounter.routeSequence || 0);
    var incomingTailIndex = clamp(Math.floor(Number(data.tail) || 0), 0, GHOST_TRAIN_WAGON_COUNT);
    var incomingRearGunSequence = Math.max(0, Number(data.rearGunSeq) || 0);
    var rearGunReplicaShots = 0;
