    encounter.actionSequence = Math.max(0, Number(data.actionSeq) || 0);
    encounter.actionTimer = incomingDefeated ? 0 : Math.max(0, Number(data.actionTimeLeft) || 0);
    encounter.actionDuration = incomingDefeated ? 0 : Math.max(encounter.actionTimer, Number(data.actionDuration) || 0);
    encounter.attackKind = encounter.action;
    encounter.attackSide = Number(data.attackSide) < 0 ? -1 : 1;
    encounter.detachSequence = Math.max(0, Number(data.detachSeq) || 0);
    boss.action = encounter.action;
    boss.actionSequence = encounter.actionSequence;
    boss.actionTimer = encounter.actionTimer;
    boss.actionDuration = encounter.actionDuration;
    boss.speed = getGhostTrainSpeed(encounter);
