      encounter.replicaNetworkEngineDistance = findClosestGhostTrainTrackDistance(encounter.replicaTrackRenderPoints, boss.targetX, boss.targetZ);
      encounter.replicaTrackRevealDistance = encounter.replicaTrackRenderPoints[encounter.replicaTrackRenderPoints.length - 1].d;
