        updateGhostTrainAttachedTransforms(encounter, 0);
        updateGhostTrainTunnelSegmentVisibility(encounter);
        encounter.deathVisualProgress = 0;
        encounter.deathBurstOne = false;
        encounter.deathBurstTwo = false;
