      clone.sourcePlayerId = multiplayerState.playerOrder[clone.sourceSlot] || clone.sourcePlayerId || "";
      clone.hp = Math.max(0, Number(incomingClone.hp) || 0);
      clone.maxHp = Math.max(1, Number(incomingClone.maxHp) || clone.maxHp || 1);
