    var edgeMaterial = mats.oilBaronWarning.clone();
    edgeMaterial.color.setHex(0xffbd54);
    edgeMaterial.opacity = 0.72;
    edgeMaterial.forceSinglePass = true;
    var arrowMaterial = mats.oilBaronWarning.clone();
    arrowMaterial.color.setHex(0xffe0a0);
