    leftEdge.scale.set(0.14, OIL_BARON_CANE_RANGE, 1);
    var rightEdge = addTelegraphPlane("cane-danger-edge-right", edgeMaterial, false);
    rightEdge.position.x = OIL_BARON_CANE_HALF_WIDTH;
    rightEdge.position.z = OIL_BARON_CANE_RANGE * 0.5;
    rightEdge.scale.set(0.14, OIL_BARON_CANE_RANGE, 1);
    var centerLine = addTelegraphPlane("cane-danger-center", edgeMaterial, false);
    centerLine.position.z = OIL_BARON_CANE_RANGE * 0.5;
