    impactRing.position.set(0, 0.095, OIL_BARON_CANE_RANGE);
    impactRing.scale.setScalar(OIL_BARON_CANE_HALF_WIDTH * 0.92);
    impactRing.renderOrder = 8;
    impactRing.castShadow = false;
    impactRing.receiveShadow = false;
    impactRing.userData.disposeGeometry = false;
    impactRing.userData.disposeMaterial = true;
