    group.userData.edgeMaterial = edgeMaterial;
    group.userData.arrowMaterial = arrowMaterial;
    group.userData.impactMaterial = impactMaterial;
    group.userData.range = OIL_BARON_CANE_RANGE;
    group.userData.halfWidth = OIL_BARON_CANE_HALF_WIDTH;
    group.visible = false;
    effectRoot.add(group);
