  function createOilBaronDebtChainLinkGeometry() {
    // A shallow extruded oval keeps the tube thickness even, unlike a scaled
    // torus. Rotating the long axis onto local +Z lets every instance follow
    // the cable tangent and roll by ninety degrees into its neighbours.
    var outer = new THREE.Shape();
    outer.absellipse(0, 0, 0.34, 0.22, 0, Math.PI * 2, false, 0);
    var opening = new THREE.Path();
    opening.absellipse(0, 0, 0.19, 0.085, 0, Math.PI * 2, true, 0);
    outer.holes.push(opening);
    var geometry = new THREE.ExtrudeGeometry(outer, {
      curveSegments: 10,
      steps: 1,
      depth: 0.11,
      bevelEnabled: true,
      bevelThickness: 0.022,
      bevelSize: 0.018,
      bevelSegments: 1,
    });
    geometry.translate(0, 0, -0.055);
    geometry.rotateY(-Math.PI / 2);
    if (typeof geometry.computeVertexNormals === "function") geometry.computeVertexNormals();
    return geometry;
  }

  function getOilBaronDebtChainLinkMaterial() {
    // All physical chains use the same immutable, vertex-coloured finish.
    // Sharing it avoids compiling/retaining one identical material per tether.
    if (oilBaronDebtChainLinkMaterial) return oilBaronDebtChainLinkMaterial;
    oilBaronDebtChainLinkMaterial = mats.oilBaronBrass.clone();
    oilBaronDebtChainLinkMaterial.color.setHex(0xffffff);
    oilBaronDebtChainLinkMaterial.metalness = 0.9;
    oilBaronDebtChainLinkMaterial.roughness = 0.24;
    oilBaronDebtChainLinkMaterial.emissive = oilBaronDebtChainLinkMaterial.emissive || new THREE.Color(0x160b02);
    oilBaronDebtChainLinkMaterial.emissive.setHex(0x160b02);
    oilBaronDebtChainLinkMaterial.emissiveIntensity = 0.42;
    return oilBaronDebtChainLinkMaterial;
  }

  function retainOilBaronDebtChainLinkMesh(mesh) {
    if (
      !mesh || !mesh.isInstancedMesh || mesh.isBatchedMesh ||
      oilBaronDebtChainLinkMeshPool.length >= OIL_BARON_MAX_DEBT_CHAINS ||
      (mesh.userData && mesh.userData.oilBaronGpuDisposed)
    ) return false;
    if (mesh.parent) mesh.parent.remove(mesh);
    mesh.count = 0;
    mesh.visible = false;
    mesh.frustumCulled = true;
    if (mesh.layers) mesh.layers.mask = 1;
    mesh.userData = mesh.userData || {};
    mesh.userData.oilBaronDebtLinkPooled = true;
    oilBaronDebtChainLinkMeshPool.push(mesh);
    return true;
  }

  function acquireOilBaronDebtChainLinkMesh() {
    var mesh = oilBaronDebtChainLinkMeshPool.pop() || null;
    if (!mesh) return null;
    mesh.count = 0;
    mesh.visible = true;
    mesh.frustumCulled = true;
    if (mesh.layers) mesh.layers.mask = 1;
    mesh.userData = mesh.userData || {};
    mesh.userData.oilBaronDebtLinkPooled = false;
    return mesh;
  }

  function createOilBaronDebtAccessoryBatchMesh(parent, key, sourceMesh) {
    if (!sourceMesh || !sourceMesh.geometry || !sourceMesh.material) return null;
    var mesh = new THREE.InstancedMesh(sourceMesh.geometry, sourceMesh.material, OIL_BARON_MAX_DEBT_CHAINS);
    mesh.name = "oil-baron-debt-batch-" + key;
    mesh.count = 0;
    mesh.visible = false;
    mesh.frustumCulled = true;
    mesh.castShadow = !!sourceMesh.castShadow;
    mesh.receiveShadow = !!sourceMesh.receiveShadow;
    mesh.renderOrder = sourceMesh.renderOrder || 0;
    mesh.boundingSphere = new THREE.Sphere();
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    mesh.userData.noDebris = true;
    if (mesh.instanceMatrix && THREE.DynamicDrawUsage != null) mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    if (!sourceMesh.geometry.boundingSphere && typeof sourceMesh.geometry.computeBoundingSphere === "function") {
      sourceMesh.geometry.computeBoundingSphere();
    }
    parent.add(mesh);
    return {
      mesh: mesh,
      count: 0,
      previousCount: 0,
      radius: sourceMesh.geometry.boundingSphere ? sourceMesh.geometry.boundingSphere.radius : 0.75,
      minX: Infinity,
      minY: Infinity,
      minZ: Infinity,
      maxX: -Infinity,
      maxY: -Infinity,
      maxZ: -Infinity,
    };
  }

  function getOilBaronDebtAccessoryBatch(encounter, sampleParts) {
    if (!encounter || typeof THREE.InstancedMesh !== "function") return null;
    if (encounter.debtAccessoryBatch) return encounter.debtAccessoryBatch;
    if (!sampleParts) return null;
    var group = new THREE.Group();
    group.name = "oil-baron-debt-accessory-batches";
    var sources = {
      cuffDark: sampleParts.cuffDark,
      cuffGold: sampleParts.cuffGold,
      lockBody: sampleParts.lockBody,
      lockFace: sampleParts.lockFace,
      sourceCoupler: sampleParts.sourceCoupler,
      castHeadCore: sampleParts.castHeadCore,
      castHeadRing: sampleParts.castHeadRing,
      healthBack: sampleParts.healthBack,
      healthFill: sampleParts.healthFill,
    };
    var specs = {};
    var keys = Object.keys(sources);
    for (var keyIndex = 0; keyIndex < keys.length; keyIndex++) {
      var key = keys[keyIndex];
      specs[key] = createOilBaronDebtAccessoryBatchMesh(group, key, sources[key]);
      if (!specs[key]) {
        removeObject3D(group);
        return null;
      }
    }
    var batch = {
      group: group,
      specs: specs,
      keys: keys,
      dirty: true,
      syncCount: 0,
      matrixUploads: 0,
      visibleDrawCalls: 0,
      shadowDrawCalls: 0,
    };
    encounter.debtAccessoryBatch = batch;
    effectRoot.add(group);
    return batch;
  }

  function configureOilBaronDebtChainAccessoryBatch(chain, encounter) {
    var parts = chain && chain.group && chain.group.userData;
    var batch = getOilBaronDebtAccessoryBatch(encounter, parts);
    if (!chain || !parts || !batch) return false;
    var keys = batch.keys;
    for (var keyIndex = 0; keyIndex < keys.length; keyIndex++) {
      var object = parts[keys[keyIndex]];
      if (object) object.visible = false;
    }
    chain.usesAccessoryBatch = true;
    parts.usesAccessoryBatch = true;
    batch.dirty = true;
    return true;
  }

  function resetOilBaronDebtAccessorySpec(spec) {
    spec.previousCount = spec.count;
    spec.count = 0;
    spec.minX = Infinity;
    spec.minY = Infinity;
    spec.minZ = Infinity;
    spec.maxX = -Infinity;
    spec.maxY = -Infinity;
    spec.maxZ = -Infinity;
  }

  function stageOilBaronDebtAccessory(spec, object, parentMatrix) {
    if (!spec || !object || spec.count >= OIL_BARON_MAX_DEBT_CHAINS) return false;
    object.updateMatrix();
    if (parentMatrix) oilBaronDebtAccessoryMatrixScratch.multiplyMatrices(parentMatrix, object.matrix);
    else oilBaronDebtAccessoryMatrixScratch.copy(object.matrix);
    spec.mesh.setMatrixAt(spec.count++, oilBaronDebtAccessoryMatrixScratch);
    var elements = oilBaronDebtAccessoryMatrixScratch.elements;
    var x = elements[12];
    var y = elements[13];
    var z = elements[14];
    var scaleX = Math.hypot(elements[0], elements[1], elements[2]);
    var scaleY = Math.hypot(elements[4], elements[5], elements[6]);
    var scaleZ = Math.hypot(elements[8], elements[9], elements[10]);
    var radius = spec.radius * Math.max(scaleX, scaleY, scaleZ);
    spec.minX = Math.min(spec.minX, x - radius);
    spec.minY = Math.min(spec.minY, y - radius);
    spec.minZ = Math.min(spec.minZ, z - radius);
    spec.maxX = Math.max(spec.maxX, x + radius);
    spec.maxY = Math.max(spec.maxY, y + radius);
    spec.maxZ = Math.max(spec.maxZ, z + radius);
    return true;
  }

  function commitOilBaronDebtAccessorySpec(spec) {
    if (!spec || !spec.mesh) return false;
    spec.mesh.count = spec.count;
    spec.mesh.visible = spec.count > 0;
    if (spec.count <= 0) return false;
    spec.mesh.instanceMatrix.needsUpdate = true;
    var centerX = (spec.minX + spec.maxX) * 0.5;
    var centerY = (spec.minY + spec.maxY) * 0.5;
    var centerZ = (spec.minZ + spec.maxZ) * 0.5;
    var halfX = (spec.maxX - spec.minX) * 0.5;
    var halfY = (spec.maxY - spec.minY) * 0.5;
    var halfZ = (spec.maxZ - spec.minZ) * 0.5;
    spec.mesh.boundingSphere.center.set(centerX, centerY, centerZ);
    spec.mesh.boundingSphere.radius = Math.hypot(halfX, halfY, halfZ);
    return true;
  }

  function syncOilBaronDebtAccessoryBatch(encounter, force) {
    var batch = encounter && encounter.debtAccessoryBatch;
    if (!batch || (!force && !batch.dirty)) return false;
    var specs = batch.specs;
    for (var resetIndex = 0; resetIndex < batch.keys.length; resetIndex++) {
      resetOilBaronDebtAccessorySpec(specs[batch.keys[resetIndex]]);
    }
    var chains = encounter.debtChains || [];
    for (var chainIndex = 0; chainIndex < chains.length; chainIndex++) {
      var chain = chains[chainIndex];
      if (
        !chain || chain.active === false || chain.hp <= 0 || !chain.usesAccessoryBatch ||
        !chain.group || chain.group.visible === false ||
        !!(chain.group.userData && chain.group.userData.oilBaronReplicaRevealPending)
      ) continue;
      var parts = chain.group.userData || {};
      if (chain.latched && parts.cuff) {
        parts.cuff.updateMatrix();
        stageOilBaronDebtAccessory(specs.cuffDark, parts.cuffDark, parts.cuff.matrix);
        stageOilBaronDebtAccessory(specs.cuffGold, parts.cuffGold, parts.cuff.matrix);
        stageOilBaronDebtAccessory(specs.lockBody, parts.lockBody, parts.cuff.matrix);
        stageOilBaronDebtAccessory(specs.lockFace, parts.lockFace, parts.cuff.matrix);
      }
      if (chain.sourceCouplerVisible) {
        stageOilBaronDebtAccessory(specs.sourceCoupler, parts.sourceCoupler, null);
      }
      if (chain.castHeadVisible && parts.castHead) {
        parts.castHead.updateMatrix();
        stageOilBaronDebtAccessory(specs.castHeadCore, parts.castHeadCore, parts.castHead.matrix);
        stageOilBaronDebtAccessory(specs.castHeadRing, parts.castHeadRing, parts.castHead.matrix);
      }
      if (chain.healthBarVisible) {
        stageOilBaronDebtAccessory(specs.healthBack, parts.healthBack, null);
        stageOilBaronDebtAccessory(specs.healthFill, parts.healthFill, null);
      }
    }
    var drawCalls = 0;
    var shadowDrawCalls = 0;
    var uploads = 0;
    for (var commitIndex = 0; commitIndex < batch.keys.length; commitIndex++) {
      var spec = specs[batch.keys[commitIndex]];
      if (commitOilBaronDebtAccessorySpec(spec)) {
        drawCalls += 1;
        uploads += 1;
        if (spec.mesh.castShadow) shadowDrawCalls += 1;
      }
    }
    batch.group.visible = drawCalls > 0;
    batch.visibleDrawCalls = drawCalls;
    batch.shadowDrawCalls = shadowDrawCalls;
    batch.matrixUploads += uploads;
    batch.syncCount += 1;
    batch.dirty = false;
    return true;
  }

  function stageOilBaronDebtAccessoryKeyForChain(spec, key, chain) {
    if (!spec || !chain || !chain.group || !chain.usesAccessoryBatch) return false;
    var parts = chain.group.userData || {};
    if (key === "cuffDark" || key === "cuffGold" || key === "lockBody" || key === "lockFace") {
      if (!chain.latched || !parts.cuff || !parts[key]) return false;
      parts.cuff.updateMatrix();
      return stageOilBaronDebtAccessory(spec, parts[key], parts.cuff.matrix);
    }
    if (key === "sourceCoupler") {
      return chain.sourceCouplerVisible
        ? stageOilBaronDebtAccessory(spec, parts.sourceCoupler, null)
        : false;
    }
    if (key === "castHeadCore" || key === "castHeadRing") {
      if (!chain.castHeadVisible || !parts.castHead || !parts[key]) return false;
      parts.castHead.updateMatrix();
      return stageOilBaronDebtAccessory(spec, parts[key], parts.castHead.matrix);
    }
    if (key === "healthBack" || key === "healthFill") {
      return chain.healthBarVisible
        ? stageOilBaronDebtAccessory(spec, parts[key], null)
        : false;
    }
    return false;
  }

  function captureOilBaronDebtAccessorySpecState(spec) {
    return {
      count: Math.max(0, Number(spec && spec.count) || 0),
      minX: Number(spec && spec.minX),
      minY: Number(spec && spec.minY),
      minZ: Number(spec && spec.minZ),
      maxX: Number(spec && spec.maxX),
      maxY: Number(spec && spec.maxY),
      maxZ: Number(spec && spec.maxZ),
    };
  }

  function applyOilBaronDebtAccessorySpecState(spec, stateValue, updateBuffer) {
    if (!spec || !spec.mesh || !stateValue) return false;
    spec.count = Math.max(0, Number(stateValue.count) || 0);
    spec.minX = stateValue.minX;
    spec.minY = stateValue.minY;
    spec.minZ = stateValue.minZ;
    spec.maxX = stateValue.maxX;
    spec.maxY = stateValue.maxY;
    spec.maxZ = stateValue.maxZ;
    spec.mesh.count = spec.count;
    spec.mesh.visible = spec.count > 0;
    if (updateBuffer && spec.mesh.instanceMatrix) spec.mesh.instanceMatrix.needsUpdate = true;
    if (spec.count > 0) {
      var centerX = (spec.minX + spec.maxX) * 0.5;
      var centerY = (spec.minY + spec.maxY) * 0.5;
      var centerZ = (spec.minZ + spec.maxZ) * 0.5;
      var halfX = (spec.maxX - spec.minX) * 0.5;
      var halfY = (spec.maxY - spec.minY) * 0.5;
      var halfZ = (spec.maxZ - spec.minZ) * 0.5;
      spec.mesh.boundingSphere.center.set(centerX, centerY, centerZ);
      spec.mesh.boundingSphere.radius = Math.hypot(halfX, halfY, halfZ);
    }
    return spec.count > 0;
  }

  function disposeOilBaronDebtAccessoryBatch(encounter) {
    var batch = encounter && encounter.debtAccessoryBatch;
    if (!batch) return false;
    if (batch.group) retireOilBaronObject3D(batch.group);
    encounter.debtAccessoryBatch = null;
    return true;
  }

