      preacherCassockRight: cassockRight,
      preacherCollar: collar,
      preacherStoleLeft: stoleLeft,
      preacherStoleRight: stoleRight,
      preacherStoleCrossLeftH: stoleCrossLeftH,
      preacherStoleCrossLeftV: stoleCrossLeftV,
      preacherStoleCrossRightH: stoleCrossRightH,
      preacherStoleCrossRightV: stoleCrossRightV,
      preacherHat: hatRig,
      preacherBookGrip: bookGrip,
      preacherBookGripArm: leftArm,
      preacherBook: bookRig,
      preacherBookCrossH: bookCrossH,
      preacherBookCrossV: bookCrossV,
      preacherCrossGrip: crossGrip,
      preacherCrossGripArm: rightArm,
