      xp: config.xp,
      group: g,
      attackCooldown: 0,
      hitPulse: 0,
      walkPhase: pooled && type === "fastZombie" ? 0 : rand(0, Math.PI * 2),
      moveAmount: 0,
      stuckTimer: 0,
      steerX: 0,
      steerZ: 1,
      facingAngle: 0,
      cachedSteerX: 0,
      cachedSteerZ: 1,
      cachedSteerWantX: 0,
      cachedSteerWantZ: 1,
      cachedSteerTimer: 0,
      avoidSide: pooled && type === "fastZombie" ? 1 : rng() < 0.5 ? -1 : 1,
      navGoal: null,
      navGoalStorage: { x: 0, z: 0, holdUntil: 0, expires: 0 },
      catchupReadyAt: 0,
      teleportCount: 0,
      pressureTargetPlayerId: "",
      pressureNearestPlayerId: "",
      pressureNearestDistance: Infinity,
      pressureRelocationCount: 0,
      pressureLastRelocatedAt: 0,
      recentCombatAt: -999,
      fireSlowTimer: 0,
      marshalStunTimer: 0,
      marshalFearTimer: 0,
      marshalFearX: 0,
      marshalFearZ: 0,
      marshalMarkTimer: 0,
      marshalBountyTimer: 0,
      marshalBounty: false,
      marshalMarksByOwner: null,
      marshalBountiesByOwner: null,
      acidCooldown: type === "spitter" ? rand(0.65, 1.35) : 0,
      acidShots: 0,
      spitWindup: 0,
      spitTarget: null,
      spitTargetStorage: { x: 0, z: 0 },
