    zombie.moveAmount = 0;
    zombie.stuckTimer = 0;
    zombie.steerX = 0;
    zombie.steerZ = 1;
    zombie.facingAngle = 0;
    zombie.cachedSteerX = 0;
    zombie.cachedSteerZ = 1;
    zombie.cachedSteerWantX = 0;
    zombie.cachedSteerWantZ = 1;
    zombie.cachedSteerTimer = 0;
    zombie.avoidSide = rng() < 0.5 ? -1 : 1;
    zombie.navGoal = null;
    zombie.catchupReadyAt = 0;
    zombie.teleportCount = 0;
    zombie.pressureTargetPlayerId = "";
    zombie.pressureNearestPlayerId = "";
    zombie.pressureNearestDistance = Infinity;
    zombie.pressureRelocationCount = 0;
    zombie.pressureLastRelocatedAt = 0;
    zombie.recentCombatAt = -999;
    zombie.fireSlowTimer = 0;
    zombie.pinDownHits = 0;
    zombie.pinDownWindowUntil = 0;
    zombie.pinDownUntil = 0;
    zombie.pinDownOwnerId = "";
    zombie.marshalStunTimer = 0;
    zombie.marshalFearTimer = 0;
    zombie.marshalFearX = 0;
    zombie.marshalFearZ = 0;
    zombie.marshalBreachContactPushAt = -99;
    zombie.marshalBreachContactPushByOwner = null;
    zombie.marshalMarkTimer = 0;
    zombie.marshalBountyTimer = 0;
    zombie.marshalBounty = false;
    zombie.marshalMarksByOwner = null;
    zombie.marshalBountiesByOwner = null;
    zombie.acidCooldown = type === "spitter" ? rand(0.65, 1.35) : 0;
