    var cellX = Math.floor((Number(entry.x) || 0) / HAZARD_SPATIAL_CELL_SIZE);
    var cellZ = Math.floor((Number(entry.z) || 0) / HAZARD_SPATIAL_CELL_SIZE);
    var key = getHazardSpatialCellKey(cellX, cellZ);
    var bucket = index.buckets.get(key);
