    if (!pointOutsideVisibleGround(patch.x, patch.z, patch.radius + FIRE_VISUAL_CULL_PAD, ground)) return true;
    var player = getLocalViewPlayer();
    if (!player) return false;
    var warningRadius = patch.radius + player.radius + MULTIPLAYER_HAZARD_WARNING_PAD;
    var dx = patch.x - player.x;
    var dz = patch.z - player.z;
