      fireFallbackVisibleCount += 1;
      var radius = Math.max(0.35, patch.radius || FIRE_PATCH_BASE_RADIUS);
      var phase = state.time * 8 + (patch.networkId || patchIndex) * 0.73;
      addFireFallbackInstance(layers.surface, patch, phase + 0.2, patch.x, 0.105, patch.z, -Math.PI / 2, 0, phase * 0.03, radius * 0.9, radius * 0.72, 1);
      addFireFallbackInstance(layers.ring, patch, phase + 0.6, patch.x, 0.125, patch.z, -Math.PI / 2, 0, -phase * 0.025, radius, radius * 0.82, 1);
