      mesh.visible = false;
      mesh.geometry = getSharedBoxGeometry(1, 1, 1);
      mesh.material.opacity = 1;
      mesh.position.set(0, -1000, 0);
      mesh.rotation.set(0, 0, 0);
      mesh.scale.setScalar(1);
