    if (progression.playerClass === "ranger") return { kind: "rifleBranch", choices: RIFLE_UPGRADES };
    if (progression.playerClass === "demolitionist") return { kind: "launcherBranch", choices: LAUNCHER_UPGRADES };
    if (progression.playerClass === "marshal") return { kind: "marshalBranch", choices: MARSHAL_UPGRADES };
