      state.launcherUpgradePending = false;
      state.launcherUpgradeOffered = true;
      state.launcherMagazineMultiplier = launcherSpec.launcherMagazineMultiplier || 1;
      resizeWeaponAmmo("launcher", oldLauncherMagazine, getWeaponMagazine(WEAPONS.launcher));
      if (id === "pyrotechnician") state.launcherFireAmmoAccumulator = 0;
