    multiplayerState.lastSnapshotSequence = -1;
    multiplayerState.authoritativeWaveRemaining = null;
    multiplayerState.xpOrbSnapshotTimer = 0;
    multiplayerState.persistentWorldSnapshotTimer = 0;
    multiplayerState.networkBulletId = 1;
