      incomingCoalescedSnapshots: 0,
      incomingCoalescedInputs: 0,
      incomingBridgeCoalescedSnapshots: 0,
      incomingBridgeCoalescedInputs: 0,
      adaptiveSnapshotHz: MULTIPLAYER_SNAPSHOT_RATE_FAST,
      eventMessages: 0,
      eventBytes: 0,
      enemyWireBytes: 0,
      enemyLegacyBytes: 0,
      lastEnemyWireBytes: 0,
      lastEnemyReplicatedCount: 0,
      playerWireBytes: 0,
      playerLegacyBytes: 0,
