    addSmokePuff(start.x - dir.x * 0.18, start.y, start.z - dir.z * 0.18, weapon.id === "launcher" ? 0.55 : 0.28, weapon.id === "launcher" ? 0.48 : 0.28);
    if (weapon.id === "revolver") playRevolverShotSound(start, dir, muzzleSide, isBigIronShot(weapon));
    else if (weapon.id === "rifle") playRifleShotSound(start, dir, predictedChainLightning);
    else if (weapon.id === "launcher") playLauncherLaunchSound(start, dir);
    else if (weapon.id === "coachGun") playCoachGunShotSound(start, dir, !!fireCost.lastShell);
    var particleCount = weapon.id === "launcher" ? 10 : weapon.id === "rifle" ? 4 : 6;
