      if (isOilBaronDerrickInsideViewerRect(derrick, primaryRect, pad)) primaryDerrickIds.push(id);
      if (isOilBaronDerrickInsideViewerRect(derrick, respawnRect, pad)) respawnDerrickIds.push(id);
      if (isOilBaronDerrickInWireScope(derrick, defeated, primaryRect, respawnRect)) scopedDerrickIds.push(id);
