      if (!op || !op.state || op.kind >= 2) return;
      if (op.kind === 1 && !(op.mask & MULTIPLAYER_ENEMY_UPDATE_POSITION)) return;
      var x = Math.round(Number(op.state.x));
      var z = Math.round(Number(op.state.z));
