      id: op.id,
      kind: op.kind,
      state: op.state ? Object.assign({}, op.state) : null,
      mask: op.mask || 0,
      revision: Math.max(0, op.revision || 0),
      lastSentTick: Math.max(0, op.lastSentTick || 0),
