    if (op.kind === 2) return 7;
    if (op.kind === 0) return 6;
    if (op.mask & MULTIPLAYER_ENEMY_UPDATE_HP) return 5;
    if (op.mask & MULTIPLAYER_ENEMY_UPDATE_SPITTER) return 4;
