    if (!ops.length) return [];
    var minimumBytes = 12;
    for (var minimumIndex = 0; minimumIndex < ops.length; minimumIndex++) {
      minimumBytes += 2 + getMultiplayerEnemyOpPayloadByteLength(ops[minimumIndex]);
    }
    if (minimumBytes <= byteBudget) {
      var fullSorted = ops.slice().sort(function (first, second) { return first.id - second.id; });
      if (getPackedMultiplayerEnemyOpsByteLength(fullSorted, keyframe, revision) <= byteBudget) return fullSorted;
    }

