      player: player,
      sequence: snapshotSequence,
      keyframe: keyframe,
      epoch: epoch,
      chunkIndex: chunkIndex,
      chunkCount: chunkCount,
      finalChunk: keyframe && chunkIndex === chunkCount - 1,
      viewTransition: !!(transfer && transfer.viewTransition),
      ops: ops,
