  function applyGuestProjectileSpawnEffects(entry, bullet, start) {
    var type = String(bullet.type || "revolver");
    var dir = { x: bullet.dirX, z: bullet.dirZ };
    var sound = null;
    var emitVisuals = !pointOutsideVisibleGround(
      start.x,
      start.z,
      2,
      getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch)
    );
    if (type === "revolver") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xffd36b, 1.7, 5, 0.08);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.28, 0.28);
      }
      playRevolverShotSound(start, dir, 0, false);
      sound = "revolver";
    } else if (type === "rifle") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xffd36b, 1.7, 5, 0.08);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.28, 0.28);
      }
      playRifleShotSound(start, dir, !!entry.chainLightning);
      sound = "rifle";
    } else if (type === "launcher") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xff7a24, 3.2, 8, 0.16);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.55, 0.48);
      }
      playLauncherLaunchSound(start, dir);
      sound = "launcher";
    }
    multiplayerState.guestProjectileSoundLog.push({
      id: entry.id,
      type: type,
      sound: sound,
    });
    if (multiplayerState.guestProjectileSoundLog.length > MULTIPLAYER_COMBAT_EVENT_HISTORY * 2) {
      multiplayerState.guestProjectileSoundLog.splice(0, multiplayerState.guestProjectileSoundLog.length - MULTIPLAYER_COMBAT_EVENT_HISTORY * 2);
    }
  }

  function getGuestProjectileVisualKind(type, chainLightning) {
    if (type === "launcher") return "launcher";
    if (type === "launcherFireShard") return "fireShard";
    if (type === "rifle" && chainLightning) return "electric";
    return "standard";
  }

  function createGuestProjectileVisual(type, start, angle, size, chainLightning) {
    if (type === "launcherFireShard") return createLauncherFireShardMesh(start.x, start.z, angle);
    var weapon = type === "launcherShrapnel"
      ? WEAPONS.revolver
      : WEAPONS[type] || (type.indexOf("launcher") === 0 ? WEAPONS.launcher : WEAPONS.revolver);
    return createProjectileMesh(weapon, start, angle, size, { electric: type === "rifle" && !!chainLightning });
  }

  function reconcileGuestProjectileVisual(bullet, type, size, chainLightning) {
    if (!bullet) return;
    var expectedKind = getGuestProjectileVisualKind(type, chainLightning);
    var currentKind = bullet.visual && bullet.visual.kind || "";
    if (!bullet.mesh || currentKind !== expectedKind) {
      var start = { x: bullet.x, y: bullet.y, z: bullet.z };
      if (bullet.visual) releaseProjectileVisual(bullet.visual);
      else if (bullet.mesh) removeObject3D(bullet.mesh);
      bullet.mesh = createGuestProjectileVisual(type, start, Math.atan2(bullet.dirX || 0, getFiniteMultiplayerNumber(bullet.dirZ, 1)), size, chainLightning);
      bullet.visual = getProjectileVisualForObject(bullet.mesh);
      return;
    }
    if (currentKind === "standard") {
      bullet.mesh.scale.set(size.width, size.width, size.length);
      syncStandardProjectileVisual(bullet.visual);
    }
  }

  function applyMultiplayerBulletSnapshot(entries, reconcileMissing, snapshotTime) {
    var seen = Object.create(null);
    var receivedAt = performance.now();
    var authoritativeSampleTime = Number(snapshotTime);
    var hasAuthoritativeSampleTime = Number.isFinite(authoritativeSampleTime);
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      var key = String(entry.id);
      if (multiplayerState.guestProjectileTombstones[key]) {
        if (multiplayerState.guestBulletMap[key]) removeGuestMultiplayerBullet(key, multiplayerState.guestBulletMap[key]);
        continue;
      }
      var remainingLife = Math.max(0, Number(entry.life) || 0);
      if (remainingLife <= 0.001) {
        if (multiplayerState.guestBulletMap[key]) removeGuestMultiplayerBullet(key, multiplayerState.guestBulletMap[key]);
        continue;
      }
      seen[key] = true;
      var bullet = multiplayerState.guestBulletMap[key];
      var created = false;
      if (!bullet) {
        var start = {
          x: Number.isFinite(Number(entry.startX)) ? Number(entry.startX) : Number(entry.x) || 0,
          y: Number.isFinite(Number(entry.startY)) ? Number(entry.startY) : Number(entry.y) || 1,
          z: Number.isFinite(Number(entry.startZ)) ? Number(entry.startZ) : Number(entry.z) || 0,
        };
        var projectileType = String(entry.type || "revolver");
        var clientFireSequence = Math.max(0, Math.floor(Number(entry.clientFireSequence) || 0));
        var projectileWeapon = projectileType === "launcherShrapnel"
          ? WEAPONS.revolver
          : WEAPONS[projectileType] || (projectileType.indexOf("launcher") === 0 ? WEAPONS.launcher : WEAPONS.revolver);
        var entrySpeed = Math.max(0, Number(entry.speed) || projectileWeapon.speed);
        var sampleDistance = Math.hypot(
          (Number(entry.x) || 0) - start.x,
          (Number(entry.z) || 0) - start.z
        );
        var projectileSampleAge = entrySpeed > 0.001 ? sampleDistance / entrySpeed : 0;
        var projectileArcMaxLife = Math.max(0.05, projectileSampleAge + remainingLife);
        var predictionRecord = getGuestPredictedShotRecord(entry.ownerId || "", projectileType, clientFireSequence);
        bullet = takePredictedMultiplayerProjectile(entry.ownerId || "", projectileType, clientFireSequence);
        var adoptedPrediction = !!bullet;
        var locallyPredictedShot = adoptedPrediction || !!predictionRecord;
        if (adoptedPrediction) {
          bullet.networkId = entry.id;
          bullet.networkLocallyPredicted = true;
          bullet.ownerPlayerId = entry.ownerId || "";
          bullet.type = projectileType;
          bullet.speed = entrySpeed;
        } else {
          var size = {
            width: Math.max(0.04, Number(entry.visualWidth) || getWeaponProjectileVisualSize(projectileWeapon, false).width),
            length: Math.max(0.12, Number(entry.visualLength) || getWeaponProjectileVisualSize(projectileWeapon, false).length),
          };
          var mesh = createGuestProjectileVisual(projectileType, start, Math.atan2(Number(entry.dirX) || 0, getFiniteMultiplayerNumber(entry.dirZ, 1)), size, !!entry.chainLightning);
          bullet = {
            networkId: entry.id,
            ownerPlayerId: entry.ownerId || "",
            type: projectileType,
            x: start.x,
            y: start.y,
            z: start.z,
            dirX: Number(entry.dirX) || 0,
            dirZ: getFiniteMultiplayerNumber(entry.dirZ, 1),
            speed: entrySpeed,
            life: remainingLife,
            maxLife: projectileArcMaxLife,
            age: projectileSampleAge,
            hitRadius: Math.max(0.01, Number(entry.hitRadius) || projectileWeapon.hitRadius || 0.1),
            networkLocallyPredicted: locallyPredictedShot,
            visual: getProjectileVisualForObject(mesh),
            mesh: mesh,
          };
          created = true;
          state.bullets.push(bullet);
        }
        bullet.clientFireSequence = clientFireSequence;
        multiplayerState.guestBulletMap[key] = bullet;
        if (predictionRecord) predictionRecord.bulletKey = key;
        if (!locallyPredictedShot) applyGuestProjectileSpawnEffects(entry, bullet, start);
        var owner = getMultiplayerPlayer(bullet.ownerPlayerId);
        if (!locallyPredictedShot && owner && owner.entity && !owner.local) {
          var kick = projectileType === "launcher" ? 1 : projectileType === "rifle" ? 0.72 : 0.55;
          owner.entity.shootKick = Math.max(owner.entity.shootKick || 0, kick);
        }
      }
      bullet.networkTargetX = Number(entry.x) || 0;
      bullet.networkTargetY = Number(entry.y) || 1;
      bullet.networkTargetZ = Number(entry.z) || 0;
      bullet.networkTargetAt = receivedAt;
      bullet.networkTargetSampleTime = hasAuthoritativeSampleTime ? authoritativeSampleTime : null;
      bullet.networkSampleLead = hasAuthoritativeSampleTime
        ? clamp(state.time - authoritativeSampleTime, 0, MULTIPLAYER_PROJECTILE_SAMPLE_LEAD_MAX)
        : 0;
      bullet.dirX = Number(entry.dirX) || 0;
      bullet.dirZ = getFiniteMultiplayerNumber(entry.dirZ, 1);
      bullet.type = String(entry.type || bullet.type || "revolver");
      if (Number.isFinite(Number(entry.speed)) && Number(entry.speed) >= 0) bullet.speed = Number(entry.speed);
      bullet.clientFireSequence = Math.max(0, Math.floor(Number(entry.clientFireSequence) || bullet.clientFireSequence || 0));
      bullet.hitRadius = Math.max(0.01, Number(entry.hitRadius) || bullet.hitRadius || 0.1);
      bullet.visualWidth = Math.max(0.04, Number(entry.visualWidth) || bullet.visualWidth || 0.1);
      bullet.visualLength = Math.max(0.12, Number(entry.visualLength) || bullet.visualLength || 0.5);
      bullet.chainLightning = !!entry.chainLightning;
      bullet.piercing = !!entry.piercing;
      if (bullet.type === "launcher") {
        var launcherSpeed = Math.max(0.001, Number(bullet.speed) || WEAPONS.launcher.speed);
        var launcherStartX = Number.isFinite(Number(entry.startX)) ? Number(entry.startX) : bullet.x;
        var launcherStartZ = Number.isFinite(Number(entry.startZ)) ? Number(entry.startZ) : bullet.z;
        var launcherSampleAge = Math.hypot(
          bullet.networkTargetX - launcherStartX,
          bullet.networkTargetZ - launcherStartZ
        ) / launcherSpeed;
        var launcherMaxLife = Math.max(0.05, launcherSampleAge + remainingLife);
        bullet.networkArcSampleAge = launcherSampleAge;
        bullet.networkArcMaxLife = launcherMaxLife;
        if (!Number.isFinite(Number(bullet.age))) bullet.age = launcherSampleAge;
        if (created) bullet.age = launcherSampleAge;
        bullet.maxLife = launcherMaxLife;
      }
      reconcileGuestProjectileVisual(bullet, String(entry.type || bullet.type || "revolver"), {
        width: bullet.visualWidth,
        length: bullet.visualLength,
      }, bullet.chainLightning);
      bullet.mesh.rotation.y = Math.atan2(bullet.dirX, bullet.dirZ);
      bullet.life = remainingLife;
      if (entry.minimumVisibleMs) {
        bullet.networkMinimumVisibleUntil = Math.max(
          bullet.networkMinimumVisibleUntil || 0,
          receivedAt + Math.max(MULTIPLAYER_PROJECTILE_MIN_VISIBLE_MS, Number(entry.minimumVisibleMs) || 0)
        );
      }
      bullet.networkExpiresAt = state.time + Math.max(
        0,
        remainingLife - (Number(bullet.networkSampleLead) || 0)
      ) + MULTIPLAYER_GUEST_BULLET_EXPIRY_GRACE;
      var recoverFromVisualContact = false;
      if (bullet.networkVisualContactAt) {
        var contactKind = String(bullet.networkVisualContactKind || "enemy");
        var contactTarget = null;
        if (contactKind === "enemy") {
          contactTarget = multiplayerState.guestEnemyMap[String(bullet.networkVisualContactEnemyId || "")];
          if (!contactTarget) contactTarget = findActiveBossDamageTargetByNetworkId(bullet.networkVisualContactEnemyId);
        } else if (contactKind === "player") {
          var contactPlayer = getMultiplayerPlayer(bullet.networkVisualContactPlayerId || "");
          contactTarget = contactPlayer && contactPlayer.entity;
        }
        if (contactKind === "world") {
          recoverFromVisualContact = Math.hypot(
            bullet.networkTargetX - (bullet.networkVisualContactX || bullet.x),
            bullet.networkTargetZ - (bullet.networkVisualContactZ || bullet.z)
          ) > 1.25;
        } else {
          var clearDistance = (contactTarget && contactTarget.radius || 0.75) + (bullet.hitRadius || 0.1) + 1.1;
          recoverFromVisualContact = !contactTarget || Math.hypot(
            bullet.networkTargetX - contactTarget.x,
            bullet.networkTargetZ - contactTarget.z
          ) > clearDistance;
        }
      }
      if (recoverFromVisualContact) {
        bullet.networkVisualContactAt = 0;
        bullet.networkVisualContactKind = "";
        bullet.networkVisualContactEnemyId = 0;
        bullet.networkVisualContactPlayerId = "";
        bullet.networkVisualContactX = 0;
        bullet.networkVisualContactZ = 0;
        bullet.networkVisualContactFxShown = false;
        bullet.mesh.visible = true;
      }
      if (created || recoverFromVisualContact || Math.hypot(bullet.networkTargetX - bullet.x, bullet.networkTargetZ - bullet.z) > MULTIPLAYER_INTERPOLATION_TELEPORT_DISTANCE) {
        bullet.x = bullet.networkTargetX;
        bullet.y = bullet.networkTargetY;
        bullet.z = bullet.networkTargetZ;
      }
      bullet.mesh.position.set(bullet.x, bullet.y, bullet.z);
      syncStandardProjectileVisual(bullet.visual);
    }
    if (reconcileMissing !== false) {
      Object.keys(multiplayerState.guestBulletMap).forEach(function (key) {
        if (seen[key]) return;
        var bullet = multiplayerState.guestBulletMap[key];
        if (bullet && bullet.networkPredicted) {
          var record = getGuestPredictedShotRecord(bullet.ownerPlayerId || "", bullet.type || "revolver", bullet.clientFireSequence);
          if (isLocalFireActionPending(bullet.ownerPlayerId, bullet.clientFireSequence) || record && record.result === "accepted") return;
        }
        removeGuestMultiplayerBullet(key, bullet);
      });
    }
  }

  function removeGuestMultiplayerBullet(key, bullet) {
    var replica = bullet || multiplayerState.guestBulletMap[key];
    if (replica) {
      var record = getGuestPredictedShotRecord(
        replica.ownerPlayerId || "",
        replica.type || "revolver",
        replica.clientFireSequence
      );
      if (record && record.bulletKey === String(key)) record.bulletKey = "";
      var index = state.bullets.indexOf(replica);
      if (index !== -1) removeBullet(index);
      else if (replica.visual) releaseProjectileVisual(replica.visual);
      else if (replica.mesh) removeObject3D(replica.mesh);
    }
    delete multiplayerState.guestBulletMap[key];
  }

  function startGame() {
    if (mainMenuSettingsOpen) setPauseMenuOpen(false);
    closeGameGuide(false);
    closeContractsMenu(false);
    closeUnlockShop(false);
    closeWardrobe(false);
    if (multiplayerState.active) {
      stopNearbyConnections(false);
      releaseMultiplayerPlayerEntities();
      resetMultiplayerSessionState();
      if (multiplayerLobby) setPanel(multiplayerLobby, false);
      if (multiplayerDeathPanel) setPanel(multiplayerDeathPanel, false);
      if (multiplayerResultPanel) setPanel(multiplayerResultPanel, false);
      if (multiplayerScoreboard) {
        multiplayerScoreboard.classList.remove("is-open");
        multiplayerScoreboard.hidden = true;
      }
      if (multiplayerScoreboardToggle) multiplayerScoreboardToggle.hidden = true;
    }
    if (ammoHud) ammoHud.hidden = false;
    lockLandscapeIfPossible();
    // Purchases and contract rewards affect the next hunt, never a draft that
    // is already in progress.
    soloCareerUnlockProfile = captureLiveCareerUnlockProfile();
    soloCosmeticProfile = captureLiveCosmeticProfile();
    resetRun("playing");
    beginSoloCareerRun();
    warmupGameplayEffectResources();
    warmupLauncherExplosionAudioGraph();
    if (isRifleListenSceneRequested()) setupRifleListenScene();
    setPanel(menu, false);
    setPanel(gameOverPanel, false);
    setPanel(revolverUpgradePanel, false);
    setPanel(rifleUpgradePanel, false);
    setPanel(launcherUpgradePanel, false);
    setPanel(marshalUpgradePanel, false);
    setPanel(levelUpPanel, false);
    updateModeClass();
  }

  function isMultiplayerMenuMatch() {
    return !!(multiplayerState.active && multiplayerState.phase === "match");
  }

  // Both variants of the overlay answer to one question everywhere the code
  // used to read state.paused directly: is the menu covering the game?
  function isPauseMenuOpen() {
    return !!state.paused || multiplayerMenuOpen;
  }

  function canOpenPauseMenu() {
    return state.mode === "playing" && !isIntroActive();
  }

  function clearActiveInput() {
    pointerDown = false;
    Object.keys(keys).forEach(function (code) {
      keys[code] = false;
    });
    resetTouchControls();
  }

  function getApplicationLifecyclePlugin() {
    var capacitor = window.Capacitor;
    return capacitor && capacitor.Plugins ? capacitor.Plugins.App : null;
  }

  function bindApplicationLifecycle() {
    var plugin = getApplicationLifecyclePlugin();
    if (!plugin || typeof plugin.addListener !== "function") return Promise.resolve(false);
    if (applicationLifecyclePluginBound) return Promise.resolve(true);
    if (applicationLifecycleBindingPromise) return applicationLifecycleBindingPromise;

    var bindingPromise = registerPluginListeners(plugin, [
      ["pause", handleApplicationSuspend],
      ["resume", handleApplicationResume],
    ]).then(function (outcome) {
      if (outcome.error) {
        applicationLifecycleListenerHandles = [];
        applicationLifecyclePluginBound = false;
        return false;
      }
      applicationLifecycleListenerHandles = outcome.handles;
      applicationLifecyclePluginBound = true;
      if (typeof plugin.getState === "function") {
        try {
          var signalSequenceAtRequest = applicationLifecycleSignalSequence;
          Promise.resolve(plugin.getState()).then(function (appState) {
            if (signalSequenceAtRequest !== applicationLifecycleSignalSequence) return;
            if (appState && appState.isActive === false) handleApplicationSuspend();
          }).catch(function () {});
        } catch (err) {}
      }
      return true;
    }).catch(function () {
      applicationLifecycleListenerHandles = [];
      applicationLifecyclePluginBound = false;
      return false;
    }).then(function (bound) {
      if (applicationLifecycleBindingPromise === bindingPromise) {
        applicationLifecycleBindingPromise = null;
      }
      return bound;
    });
    applicationLifecycleBindingPromise = bindingPromise;
    return bindingPromise;
  }

  function resetApplicationFrameClocks() {
    lastFrame = performance.now();
    lastRuntimeNetworkFlushAt = lastFrame;
    pendingSimulationTime = 0;
    runtimeLongFrameStreak = 0;
  }

  function pauseAudioSchedulersForApplication() {
    if (audioState.menu.scheduler) {
      window.clearInterval(audioState.menu.scheduler);
      audioState.menu.scheduler = null;
    }
    if (audioState.game.scheduler) {
      window.clearInterval(audioState.game.scheduler);
      audioState.game.scheduler = null;
    }
  }

  function handleApplicationSuspend() {
    applicationLifecycleSignalSequence += 1;
    if (applicationSuspended) return false;
    applicationSuspended = true;
    applicationLifecycleSequence += 1;
    resetApplicationFrameClocks();
    clearActiveInput();
    root.classList.add("is-app-suspended");

    if (canOpenPauseMenu()) setPauseMenuOpen(true);
    if (renderLoopRequestId) {
      window.cancelAnimationFrame(renderLoopRequestId);
      renderLoopRequestId = 0;
    }

    pauseAudioSchedulersForApplication();
    var ctx = audioState.ctx;
    applicationAudioWasRunning = !!(ctx && ctx.state === "running");
    applicationAudioSuspendPromise = null;
    if (applicationAudioWasRunning) {
      if (audioState.masterGain) {
        applicationAudioMasterGain = Number(audioState.masterGain.gain.value);
        if (!Number.isFinite(applicationAudioMasterGain)) applicationAudioMasterGain = 1;
        audioState.masterGain.gain.value = 0;
      }
      if (typeof ctx.suspend === "function") {
        try {
          var suspendResult = ctx.suspend();
          applicationAudioSuspendPromise =
            suspendResult && typeof suspendResult.then === "function"
              ? suspendResult.catch(function () {})
              : Promise.resolve();
        } catch (err) {}
      }
    }
    updateMenuMusicButton();
    return true;
  }

  function handleApplicationResume() {
    applicationLifecycleSignalSequence += 1;
    if (!applicationLifecyclePluginBound && !applicationLifecycleBindingPromise) {
      bindApplicationLifecycle();
    }
    if (!applicationSuspended) return false;
    applicationSuspended = false;
    var lifecycleSequence = ++applicationLifecycleSequence;
    var shouldResumeAudio = applicationAudioWasRunning;
    var pendingSuspend = applicationAudioSuspendPromise;
    applicationAudioWasRunning = false;
    applicationAudioSuspendPromise = null;
    resetApplicationFrameClocks();
    root.classList.remove("is-app-suspended");
    scheduleNextAnimationFrame();

    var restoreAudio = function () {
      if (applicationSuspended || lifecycleSequence !== applicationLifecycleSequence) return;
      var ctx = audioState.ctx;
      if (!ctx) {
        updateMenuMusicButton();
        return;
      }
      if (audioState.masterGain && shouldResumeAudio) {
        audioState.masterGain.gain.value = applicationAudioMasterGain;
      }
      var finishResume = function () {
        if (applicationSuspended || lifecycleSequence !== applicationLifecycleSequence) return;
        if (ctx.state === "running") syncMusicForMode();
        updateMenuMusicButton();
      };
      if (shouldResumeAudio && ctx.state === "suspended" && typeof ctx.resume === "function") {
        try {
          var resumeResult = ctx.resume();
          if (resumeResult && typeof resumeResult.then === "function") {
            resumeResult.then(finishResume).catch(function () {
              updateMenuMusicButton();
            });
          } else {
            finishResume();
          }
        } catch (err) {
          updateMenuMusicButton();
        }
      } else {
        finishResume();
      }
    };

    if (pendingSuspend && typeof pendingSuspend.then === "function") {
      pendingSuspend.then(restoreAudio, restoreAudio);
    } else {
      restoreAudio();
    }
    return true;
  }

  function canOpenMainMenuSettings() {
    return state.mode === "menu" &&
      !isIntroActive() &&
      !multiplayerState.active &&
      !isBlockingOverlayOpen();
  }

  function openMainMenuSettings() {
    if (!canOpenMainMenuSettings()) return false;
    mainMenuSettingsOpen = true;
    clearActiveInput();
    showPauseMenuView("settings");
    updatePauseVolumeControls();
    syncPauseMenuUi();
    if (pauseCloseBtn && typeof pauseCloseBtn.focus === "function") pauseCloseBtn.focus();
    return true;
  }

  function showPauseMenuView(view) {
    var normalizedView = view === "settings" || view === "exit-confirm" ? view : "main";
    var showSettings = normalizedView === "settings";
    var showExitConfirm = normalizedView === "exit-confirm";
    pauseMenuView = normalizedView;
    if (pauseMainPanel) pauseMainPanel.classList.toggle("is-visible", normalizedView === "main");
    if (pauseSettingsPanel) pauseSettingsPanel.classList.toggle("is-visible", showSettings);
    if (pauseExitConfirmPanel) pauseExitConfirmPanel.classList.toggle("is-visible", showExitConfirm);
    if (pauseMenuDialog) {
      pauseMenuDialog.setAttribute(
        "aria-labelledby",
        showSettings
          ? "pause-settings-title"
          : showExitConfirm
            ? "pause-exit-confirm-title"
            : "pause-menu-title"
      );
      if (showExitConfirm) pauseMenuDialog.setAttribute("aria-describedby", "pause-exit-confirm-description");
      else pauseMenuDialog.removeAttribute("aria-describedby");
    }
    if (normalizedView === "main") updatePauseChallengePanel();
    if (showSettings) {
      updatePauseVolumeControls();
      updateGraphicsSettingsUi();
    }
  }

  function focusPauseControl(control) {
    if (control && typeof control.focus === "function") control.focus();
  }

  function returnFromPauseSubmenu(origin) {
    showPauseMenuView("main");
    focusPauseControl(origin || pauseContinueBtn);
  }

  function getVisiblePauseMenuControls() {
    if (!pauseMenuDialog) return [];
    return Array.prototype.slice.call(
      pauseMenuDialog.querySelectorAll('button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])')
    ).filter(function (element) {
      return !!(element.offsetWidth || element.offsetHeight || element.getClientRects().length);
    });
  }

  function trapPauseMenuFocus(event) {
    if (!event || event.code !== "Tab") return false;
    var controls = getVisiblePauseMenuControls();
    if (!controls.length) return false;
    var currentIndex = controls.indexOf(document.activeElement);
    var nextIndex = event.shiftKey
      ? (currentIndex <= 0 ? controls.length - 1 : currentIndex - 1)
      : (currentIndex === -1 || currentIndex >= controls.length - 1 ? 0 : currentIndex + 1);
    event.preventDefault();
    focusPauseControl(controls[nextIndex]);
    return true;
  }

  function syncPauseMenuUi() {
    var open = isPauseMenuOpen() || mainMenuSettingsOpen;
    if (pauseMenu) {
      pauseMenu.classList.toggle("is-visible", open);
      pauseMenu.classList.toggle("is-main-menu-settings", mainMenuSettingsOpen);
      pauseMenu.classList.toggle("is-multiplayer-menu", multiplayerMenuOpen);
      pauseMenu.setAttribute("aria-hidden", open ? "false" : "true");
    }
    if (pauseMenuBtn) pauseMenuBtn.setAttribute("aria-expanded", open ? "true" : "false");
    if (menuSettingsBtn) menuSettingsBtn.setAttribute("aria-expanded", mainMenuSettingsOpen ? "true" : "false");
    updateModeClass();
  }

  function setPauseMenuOpen(open) {
    var restoreMenuSettingsFocus = mainMenuSettingsOpen && !open;
    var wasPaused = isPauseMenuOpen();
    mainMenuSettingsOpen = false;
    var shouldOpen = !!open && canOpenPauseMenu();
    if (!shouldOpen && controlLayoutState.editing) finishControlLayoutEdit(false);
    // In a live match only the overlay opens. The simulation keeps advancing,
    // and clearActiveInput below plus the keydown gate stop this player from
    // acting while they read it — they stand still and stay vulnerable, which
    // is the honest cost of opening a menu mid-match.
    var duringMatch = shouldOpen && isMultiplayerMenuMatch();
    multiplayerMenuOpen = duringMatch;
    state.paused = shouldOpen && !duringMatch;
    clearActiveInput();
    if (shouldOpen) {
      showPauseMenuView("main");
      updatePauseVolumeControls();
      syncPauseMenuModeCopy();
    }
    syncPauseMenuUi();
    if (shouldOpen) focusPauseControl(pauseContinueBtn);
    if (
      restoreMenuSettingsFocus &&
      menuSettingsBtn &&
      typeof menuSettingsBtn.focus === "function"
    ) menuSettingsBtn.focus();
    else if (!shouldOpen && wasPaused) focusPauseControl(pauseMenuBtn);
  }

  // "Paused" and "this hunt will end and cannot be resumed" are both wrong in a
  // match that keeps running without you, so the overlay swaps to the keys that
  // say so. Swapping data-i18n (not textContent) keeps a later language change
  // correct — refresh re-reads the attribute we just set.
  function syncPauseMenuModeCopy() {
    var inMatch = multiplayerMenuOpen;
    var entries = [
      [pauseMenuTitle, inMatch ? "pause.multiplayerTitle" : "pause.title"],
      [pauseMenuMatchHint, "pause.multiplayerHint"],
      [pauseExitConfirmEyebrow, inMatch ? "pause.exitConfirm.multiplayerEyebrow" : "pause.exitConfirm.eyebrow"],
      [pauseExitConfirmTitle, inMatch ? "pause.exitConfirm.multiplayerTitle" : "pause.exitConfirm.title"],
      [pauseExitConfirmBody, inMatch ? "pause.exitConfirm.multiplayerBody" : "pause.exitConfirm.body"],
    ];
    for (var i = 0; i < entries.length; i++) {
      var element = entries[i][0];
      if (!element) continue;
      element.setAttribute("data-i18n", entries[i][1]);
      if (gameI18n && typeof gameI18n.refresh === "function") gameI18n.refresh(element);
    }
    if (pauseMenuMatchHint) {
      pauseMenuMatchHint.hidden = !inMatch;
      pauseMenuMatchHint.setAttribute("aria-hidden", inMatch ? "false" : "true");
    }
  }

  function exitFromPauseMenu() {
    if (multiplayerMenuOpen) {
      // Leaving mid-match is a real departure: closeLocalMultiplayerLobby sends
      // match.leave online (or drops the Nearby link), releases the seat and
      // rebuilds a fresh solo map before showing the menu.
      multiplayerMenuOpen = false;
      state.paused = false;
      syncPauseMenuUi();
      closeLocalMultiplayerLobby();
      return;
    }
    exitToMainMenu();
  }

  function exitToMainMenu() {
    multiplayerMenuOpen = false;
    settleSoloCareerMastery();
    setPauseMenuOpen(false);
    closeGameGuide(false);
    closeContractsMenu(false);
    closeUnlockShop(false);
    closeWardrobe(false);
    prepareFreshMainMenuMap();
    resetRun("menu");
    soloCareerUnlockProfile = null;
    soloCosmeticProfile = null;
    careerSoloRunId = "";
    careerSoloRunStartSnapshot = null;
    lastSoloRunSummary = null;
    refreshProgressionUi();
    updateModeClass();
  }

  function openGameOverDevelopment() {
    exitToMainMenu();
    openUnlockShop();
  }

  function setupEnemyBestiaryPreview(variant) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.paused = true;
    state.enemyAnimationPreview = true;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 4.8);
    if (state.player) {
      state.player.x = center.x;
      state.player.z = center.z;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    var types = variant === "miner" || variant === "miner-damaged" ? ["armoredMiner"]
      : variant === "preacher" ? ["gravePreacher"]
        : ["armoredMiner", "gravePreacher"];
    var spacing = types.length > 1 ? 3.4 : 0;
    var entries = types.map(function (type, index) {
      var enemy = acquireZombie(type);
      enemy.x = center.x + (index - (types.length - 1) * 0.5) * spacing;
      enemy.z = center.z;
      enemy.facingAngle = 0;
      enemy.group.position.set(enemy.x, 0, enemy.z);
      enemy.group.rotation.y = 0;
      enemy.moveAmount = type === "armoredMiner" ? 0.32 : 0.18;
      if (enemy.group.userData.healthBack) enemy.group.userData.healthBack.visible = false;
      if (enemy.group.userData.healthFill) enemy.group.userData.healthFill.visible = false;
      state.enemies.push(enemy);
      dynamicRoot.add(enemy.group);
      if (variant === "miner-damaged" && type === "armoredMiner") {
        var firstArmorDebris = state.debris.length;
        enemy.renderVisible = true;
        enemy.hp = enemy.maxHp * 0.32;
        updateArmoredMinerArmorVisual(enemy);
        var armorPreviewLayout = [
          [-0.7, 0.38, -0.18, 0.18, 0.5, -0.28],
          [0.76, 0.32, 0.2, -0.22, -0.35, 0.4],
          [0.18, -0.62, -0.14, 0.35, 0.12, -0.2],
        ];
        for (var armorPreviewIndex = firstArmorDebris; armorPreviewIndex < state.debris.length; armorPreviewIndex++) {
          var armorPiece = state.debris[armorPreviewIndex];
          var armorLayout = armorPreviewLayout[armorPreviewIndex - firstArmorDebris] || armorPreviewLayout[0];
          armorPiece.x = enemy.x + armorLayout[0];
          armorPiece.y = 0.12;
          armorPiece.z = enemy.z + armorLayout[1];
          armorPiece.vx = 0;
          armorPiece.vy = 0;
          armorPiece.vz = 0;
          armorPiece.mesh.position.set(armorPiece.x, armorPiece.y, armorPiece.z);
          armorPiece.mesh.rotation.set(armorLayout[2], armorLayout[3], armorLayout[4]);
        }
      }
      updateZombieVisual(enemy);
      updateEnemyHealthBar(enemy);
      return { type: type, groupId: enemy.group.uuid, parts: enemy.group.children.length };
    });
    camera.zoom = types.length === 1 ? 4.15 : 2.25;
    camera.updateProjectionMatrix();
    cameraTarget.set(center.x, 0, center.z + 0.3);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    zombieSpatialDirty = true;
    updateModeClass();
    updateHud();
    render();
    return entries;
  }

  function setupBellRingerPreview(closeup) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.paused = false;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 2.5);
    var encounter = startBellRingerEncounter({ x: center.x, z: center.z, preview: true, aiEnabled: false });
    if (!encounter) return false;
    encounter.churches[0].captureProgress = 0.28;
    encounter.churches[1].captureProgress = 0.54;
    encounter.churches[2].captureProgress = 0.78;
    encounter.tollActive = !closeup;
    encounter.tollQueue = [{ index: -1, x: encounter.boss.x, z: encounter.boss.z }];
    encounter.tollQueueIndex = 0;
    encounter.tollWindup = closeup ? 0 : 0.82;
    encounter.tollSourceIndex = -1;
    encounter.boss.walkPhase = 1.12;
    encounter.boss.moveAmount = closeup ? 0.72 : 0.48;
    if (state.player) {
      state.player.x = center.x;
      state.player.z = center.z + (closeup ? -1.3 : -4.1);
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    camera.zoom = closeup ? 2.15 : 0.92;
    camera.updateProjectionMatrix();
    cameraTarget.set(center.x, 0, center.z);
    updateBellRingerVisuals(encounter, 0);
    updateModeClass();
    updateHud();
    render();
    return getBellRingerDiagnostics();
  }

  function setupHordeheartPreview(mode, requestedProgress) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.wave10BossKind = "hordeheart";
    state.paused = false;

    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 4.2);
    var encounter = startHordeheartEncounter({
      x: center.x,
      z: center.z,
      aiEnabled: false,
      silent: true,
    });
    if (!encounter) return false;

    var previewMode = String(mode || "whole").toLowerCase();
    var numericPreviewProgress = requestedProgress == null || requestedProgress === "" ? NaN : Number(requestedProgress);
    var previewProgress = Number.isFinite(numericPreviewProgress) ? clamp(numericPreviewProgress, 0, 1) : 0.54;
    var chunkCount = previewMode === "horde" ? 14 : previewMode === "gather" ? 42 : 0;
    encounter.hordeMaxHp = 48;
    encounter.hordeHp = 48;
    for (var chunkIndex = 0; chunkIndex < chunkCount; chunkIndex++) {
      var chunkAngle = chunkIndex / Math.max(1, chunkCount) * Math.PI * 2 + Math.sin(chunkIndex * 2.17) * 0.24;
      var chunkRadius = previewMode === "gather"
        ? 4.2 + (chunkIndex % 7) * 1.05
        : 3.2 + (chunkIndex % 5) * 1.18;
      recordHordeheartFleshChunk(
        center.x + Math.sin(chunkAngle) * chunkRadius,
        center.z + Math.cos(chunkAngle) * chunkRadius
      );
    }

    if (previewMode === "horde") {
      state.spawnLeft = 18;
      for (var zombieIndex = 0; zombieIndex < 14; zombieIndex++) {
        if (!spawnZombie()) continue;
        var zombie = state.enemies[state.enemies.length - 1];
        var zombieAngle = zombieIndex / 14 * Math.PI * 2 + (zombieIndex % 3) * 0.13;
        var zombieRadius = 5.5 + (zombieIndex % 4) * 1.55;
        zombie.x = center.x + Math.sin(zombieAngle) * zombieRadius;
        zombie.z = center.z + Math.cos(zombieAngle) * zombieRadius;
        zombie.walkPhase = zombieIndex * 0.61;
        zombie.moveAmount = 0.42;
        zombie.renderVisible = true;
        zombie.group.position.set(zombie.x, 0, zombie.z);
        updateZombieVisual(zombie);
      }
      state.spawnLeft = 0;
      state.waveInitialPressureLeft = 0;
      encounter.hordeHp = Math.max(1, encounter.hordeMaxHp - encounter.fleshChunks.length);
      syncZombieInstanceBatches();
    } else if (previewMode === "gather") {
      setHordeheartPhase(encounter, "gather", { force: true, silent: true });
      encounter.phaseTimer = HORDEHEART_GATHER_DURATION * (1 - previewProgress);
      updateHordeheartGather(encounter, 0);
    } else if (previewMode === "halves") {
      setHordeheartPhase(encounter, "halves", { force: true, silent: true });
    } else if (previewMode === "quarters" || previewMode === "final") {
      setHordeheartPhase(encounter, "quarters", { force: true, silent: true });
    } else if (previewMode === "split1") {
      setHordeheartPhase(encounter, "whole", { force: true, silent: true });
      setHordeheartPhase(encounter, "split1", { force: true, silent: true });
      encounter.phaseTimer = HORDEHEART_SPLIT_DURATION * (1 - previewProgress);
      updateHordeheartSplit(encounter, 0);
    } else if (previewMode === "split2") {
      setHordeheartPhase(encounter, "halves", { force: true, silent: true });
      setHordeheartPhase(encounter, "split2", { force: true, silent: true });
      encounter.phaseTimer = HORDEHEART_SPLIT_DURATION * (1 - previewProgress);
      updateHordeheartSplit(encounter, 0);
    } else {
      setHordeheartPhase(encounter, "whole", { force: true, silent: true });
    }

    if (state.player) {
      state.player.x = center.x;
      state.player.z = center.z;
      state.player.invuln = 999;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    camera.zoom = previewMode === "whole" ? 1.18
      : previewMode === "halves" || previewMode === "split1" ? 0.9
        : previewMode === "quarters" || previewMode === "final" || previewMode === "split2" ? 0.72 : 0.68;
    camera.updateProjectionMatrix();
    cameraTarget.set(center.x, 0, center.z);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    for (var bodyIndex = 0; bodyIndex < encounter.bodies.length; bodyIndex++) {
      updateHordeheartBodyVisual(encounter.bodies[bodyIndex], 0, previewMode !== "whole");
    }
    state.paused = true;
    updateModeClass();
    updateHordeheartHud();
    updateHud();
    render();
    return getHordeheartDiagnostics();
  }

  function setupHordeheartActionPreview(action, progress, requestedVariant, requestedSizeClass) {
    var variant = String(requestedVariant || "").toLowerCase();
    var requested = variant === "movement-lock" ? "fleshTide"
      : variant === "proximity-repulse" ? "ribBloom" : String(action || "fleshTide");
    var allowed = [
      "fleshTide", "ribBloom", "systole", "pincer", "arterialSweep", "rush", "carrionNest",
    ];
    if (allowed.indexOf(requested) < 0) requested = "fleshTide";
    var previewMode = variant === "proximity-repulse"
      ? (String(requestedSizeClass || "half").toLowerCase() === "quarter" ? "quarters" : "halves")
      : requested === "pincer" || requested === "arterialSweep" ? "halves"
      : requested === "rush" || requested === "carrionNest" ? "quarters" : "whole";
    if (!setupHordeheartPreview(previewMode)) return false;
    var encounter = state.hordeheart;
    if (!encounter || !encounter.bodies.length) return false;
    if (state.player) {
      if (variant === "movement-lock") {
        state.player.x = clamp(encounter.centerX + 11, -ARENA_W * 0.5 + state.player.radius, ARENA_W * 0.5 - state.player.radius);
        state.player.z = clamp(encounter.centerZ + 1.5, -ARENA_D * 0.5 + state.player.radius, ARENA_D * 0.5 - state.player.radius);
      } else if (variant === "proximity-repulse") {
        var previewRepulseBody = encounter.bodies[0];
        var previewOutwardX = previewRepulseBody.x - encounter.centerX;
        var previewOutwardZ = previewRepulseBody.z - encounter.centerZ;
        var previewOutwardLength = Math.max(0.001, Math.hypot(previewOutwardX, previewOutwardZ));
        var previewApproachDistance = previewMode === "quarters" ? 3.7 : 4.2;
        state.player.x = previewRepulseBody.x + previewOutwardX / previewOutwardLength * previewApproachDistance;
        state.player.z = previewRepulseBody.z + previewOutwardZ / previewOutwardLength * previewApproachDistance;
      } else {
        state.player.x = encounter.centerX;
        state.player.z = clamp(encounter.centerZ + 10, -ARENA_D * 0.5 + state.player.radius, ARENA_D * 0.5 - state.player.radius);
      }
      resolveMoverPosition(state.player, state.player.radius, 0);
      state.player.group.position.set(state.player.x, 0, state.player.z);
    }
    if (!encounter.fleshChunks.length) {
      for (var chunkIndex = 0; chunkIndex < 10; chunkIndex++) {
        var chunkAngle = chunkIndex / 10 * Math.PI * 2 + (chunkIndex % 2) * 0.21;
        recordHordeheartFleshChunk(
          encounter.centerX + Math.sin(chunkAngle) * (5.2 + chunkIndex % 3),
          encounter.centerZ + Math.cos(chunkAngle) * (5.2 + chunkIndex % 3)
        );
      }
      syncHordeheartFleshBatch(encounter);
    }
    var numericActionProgress = progress == null || progress === "" ? NaN : Number(progress);
    var actionProgress = Number.isFinite(numericActionProgress) ? clamp(numericActionProgress, 0, 1) : 0.64;
    encounter.aiEnabled = false;
    updateHordeheartPlayerMotionSamples(encounter, getHordeheartPlayerEntries(), FIXED_DT);
    if (!beginHordeheartAttack(
      encounter,
      getHordeheartPlayerEntries(),
      requested,
      variant === "movement-lock" ? "movement-lock"
        : variant === "proximity-repulse" ? "proximity-repulse" : ""
    )) return false;
    var previewAction = encounter.action;
    var duration = previewAction.duration;
    previewAction.timer = duration * actionProgress;
    var previewEvents = getHordeheartActionImpactEvents(previewAction);
    var previewMask = 0;
    for (var previewEventIndex = 0; previewEventIndex < previewEvents.length; previewEventIndex++) {
      if (actionProgress >= previewEvents[previewEventIndex].threshold) previewMask |= 1 << previewEventIndex;
    }
    previewAction.impactMask = previewMask;
    previewAction.visualImpactMask = previewMask;
    previewAction.resolved = previewMask === (1 << previewEvents.length) - 1;
    updateHordeheartActionBodyMotion(encounter, previewAction, 0);
    for (var bodyIndex = 0; bodyIndex < encounter.bodies.length; bodyIndex++) {
      var body = encounter.bodies[bodyIndex];
      var attacking = previewAction.bodyIndices.indexOf(body.index) >= 0;
      body.action = attacking ? requested : "idle";
      body.actionDuration = attacking ? duration : 0;
      body.actionTimer = attacking ? getHordeheartBodyActionTimer(previewAction, body.index) : 0;
      body.moveAmount = 0;
      if (!variant) body.facingAngle = 0;
      updateHordeheartBodyVisual(body, 0, previewMode !== "whole");
    }
    showHordeheartTelegraph(encounter, previewAction);
    placeHordeheartTelegraphAtBodies(encounter, previewAction);
    updateHordeheartTelegraphAnimation(encounter, previewAction, actionProgress);
    state.paused = true;
    updateHordeheartHud();
    updateHud();
    render();
    return getHordeheartDiagnostics();
  }

  function setupHordeheartCrawlPreview(sizeClass, requestedPhase) {
    var previewSize = String(sizeClass || "half").toLowerCase() === "quarter" ? "quarter" : "half";
    var previewMode = previewSize === "quarter" ? "quarters" : "halves";
    if (!setupHordeheartPreview(previewMode)) return false;
    var encounter = state.hordeheart;
    if (!encounter || !encounter.bodies.length) return false;
    var numericPhase = Number(requestedPhase);
    var gaitPhase = Number.isFinite(numericPhase) ? numericPhase : Math.PI * 0.5;
    encounter.aiEnabled = false;
    encounter.action = null;
    for (var bodyIndex = 0; bodyIndex < encounter.bodies.length; bodyIndex++) {
      var body = encounter.bodies[bodyIndex];
      body.action = "idle";
      body.actionDuration = 0;
      body.actionTimer = 0;
      body.moveAmount = 1;
      body.gaitPhase = gaitPhase + bodyIndex * 0.18;
      body.facingAngle = 0;
      body.pullDrive = getHordeheartFragmentPullDrive(body.sizeClass, body.gaitPhase);
      body.pullSpeedMultiplier = getHordeheartFragmentSpeedMultiplier(body.sizeClass, body.gaitPhase);
      updateHordeheartBodyVisual(body, 0, true);
    }
    state.paused = true;
    updateHordeheartHud();
    updateHud();
    render();
    return getHordeheartDiagnostics();
  }

  function setupHordeheartDeathPreview(progress) {
    if (!setupHordeheartPreview("halves")) return false;
    var encounter = state.hordeheart;
    var body = encounter && encounter.bodies[0];
    if (!encounter || !body) return false;
    var numericProgress = progress == null || progress === "" ? NaN : Number(progress);
    var decayProgress = Number.isFinite(numericProgress) ? clamp(numericProgress, 0, 1) : 0.62;
    body.hp = 0;
    body.active = false;
    body.downed = true;
    body.action = "downed";
    body.deathDuration = HORDEHEART_SPLIT_DURATION;
    body.deathStartedAt = state.time - body.deathDuration * decayProgress;
    body.actionDuration = body.deathDuration;
    body.actionTimer = body.deathDuration * decayProgress;
    body.attackFacingAngle = null;
    updateHordeheartBodyVisual(body, 0, true);
    state.paused = true;
    updateHordeheartHud();
    updateHud();
    render();
    return getHordeheartDiagnostics();
  }

  function setupSlothArchbishopPreview(mode) {
    slothArchbishopModelReviewCamera = false;
    worldRoot.visible = true;
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.wave10BossKind = "slothArchbishop";
    state.paused = false;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 3);
    var encounter = startSlothArchbishopEncounter({
      x: center.x,
      z: center.z,
      preview: true,
      aiEnabled: false,
      silent: true,
    });
    if (!encounter) return false;
    var previewMode = String(mode || "sleep").toLowerCase();
    if (previewMode === "walk" || previewMode === "awake") {
      encounter.phase = 1;
      encounter.boss.action = "idle";
      encounter.boss.actionDuration = 0;
      encounter.boss.actionTimer = 0;
      encounter.boss.hp = encounter.boss.maxHp * 0.66;
      encounter.boss.moveAmount = 0.38;
      encounter.boss.walkPhase = 1.14;
    } else if (previewMode === "shield" || previewMode === "orbit") {
      encounter.phase = 1;
      encounter.boss.action = "idle";
      encounter.boss.actionDuration = 0;
      encounter.boss.actionTimer = 0;
      encounter.boss.hp = encounter.boss.maxHp * SLOTH_ARCHBISHOP_ORBIT_SHIELD_HP_RATIO;
      encounter.boss.moveAmount = 0.12;
      encounter.boss.walkPhase = 0.72;
    } else if (previewMode === "spider" || previewMode === "unbound") {
      encounter.phase = 2;
      encounter.boss.action = "idle";
      encounter.boss.hp = encounter.boss.maxHp * 0.34;
      encounter.boss.speed = SLOTH_ARCHBISHOP_SPIDER_SPEED;
      encounter.boss.moveAmount = 0.42;
      encounter.boss.walkPhase = 1.38;
    }
    updateSlothOrbitShield(encounter, 0);
    if (encounter.orbitShieldUnlocked) {
      encounter.orbitShieldTimer = SLOTH_ARCHBISHOP_ORBIT_SHIELD_REVEAL_DURATION;
    }
    var shortLandscapePreview = window.innerWidth > window.innerHeight && window.innerHeight <= 400;
    var previewFollowZ = center.z - 4.2;
    if (shortLandscapePreview) {
      previewFollowZ = previewMode === "sleep"
        ? center.z - 1.5
        : previewMode === "spider" || previewMode === "unbound"
          ? center.z - 1.5
          : center.z - 0.5;
    }
    if (state.player) {
      state.player.x = center.x;
      state.player.z = previewFollowZ;
      state.player.invuln = 999;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    camera.zoom = previewMode === "sleep" ? 1.65 : previewMode === "spider" ? 0.96 : 1.42;
    camera.updateProjectionMatrix();
    cameraTarget.set(center.x, 0, previewFollowZ);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    updateSlothArchbishopVisuals(encounter, 0);
    updateModeClass();
    updateHud();
    render();
    return getSlothArchbishopDiagnostics();
  }

  function positionSlothArchbishopModelReviewCamera(boss) {
    if (!boss) return;
    cameraTarget.set(boss.x, 3.55, boss.z);
    if (slothArchbishopModelReviewView === "front") {
      camera.position.set(boss.x, 10, boss.z + 28);
    } else if (slothArchbishopModelReviewView === "grazing") {
      camera.position.set(boss.x - 20, 10.5, boss.z + 19);
    } else {
      camera.position.set(boss.x + 9.5, 14.5, boss.z + 25);
    }
    camera.lookAt(cameraTarget);
  }

  function setupSlothArchbishopModelPreview() {
    if (!setupSlothArchbishopPreview("walk")) return false;
    var encounter = state.slothArchbishop;
    var boss = encounter && encounter.boss;
    if (!boss) return false;
    state.paused = true;
    boss.facingAngle = 0;
    slothArchbishopModelReviewCamera = true;
    slothArchbishopModelReviewView = String(
      new URLSearchParams(window.location.search || "").get("modelView") || "reference"
    ).toLowerCase();
    worldRoot.visible = false;
    var reviewFloor = addSharedBox(dynamicRoot, 32, 0.32, 32, mats.sand, boss.x, -0.18, boss.z);
    reviewFloor.name = "sloth-archbishop-model-review-floor";
    reviewFloor.castShadow = false;
    // A dedicated three-quarter review camera mirrors the single concept-art
    // view more fairly than the steep arena camera. Gameplay previews keep the
    // production camera and are reviewed separately during interaction QA.
    camera.zoom = 4.1;
    camera.updateProjectionMatrix();
    positionSlothArchbishopModelReviewCamera(boss);
    updateSlothArchbishopVisuals(encounter, 0);
    render();
    return getSlothArchbishopDiagnostics();
  }

  function setupSlothArchbishopActionPreview(actionName, actionProgress, phaseName) {
    var requestedAction = String(actionName || "wake").toLowerCase();
    var action = requestedAction === "clap" || requestedAction === "prayerclap" || requestedAction === "prayer-clap"
      ? "prayerClap"
      : requestedAction === "lazygrip" || requestedAction === "lazy-grip" || requestedAction === "drag"
        ? "lazyGrip"
        : requestedAction === "foursides" || requestedAction === "four-sides" || requestedAction === "four"
          ? "fourSides"
          : requestedAction === "crosssweep" || requestedAction === "cross-sweep" || requestedAction === "cross"
            ? "crossSweep"
            : requestedAction;
    var allowed = [
      "wake", "guard", "sweep", "overhead", "spiderrise", "grab", "death",
      "prayerClap", "lazyGrip", "fourSides", "crossSweep",
    ];
    if (allowed.indexOf(action) < 0) action = "wake";
    var previewFinalPhase = String(phaseName || "").toLowerCase() === "spider";
    var baseMode = action === "wake"
      ? "sleep"
      : previewFinalPhase || action === "grab" || action === "death" || action === "fourSides" || action === "crossSweep"
        ? "spider"
        : "walk";
    if (!setupSlothArchbishopPreview(baseMode)) return false;
    var encounter = state.slothArchbishop;
    var boss = encounter && encounter.boss;
    if (!encounter || !boss || !state.player) return false;

    boss.action = "idle";
    boss.actionTimer = 0;
    boss.actionDuration = 0;
    boss.actionResolved = false;
    boss.targetPlayerId = "";
    boss.facingAngle = Math.PI;
    boss.moveAmount = 0;
    encounter.wakeTargets.length = 0;
    encounter.slamTargets.length = 0;
    state.player.x = boss.x + (action === "grab" || action === "lazyGrip" ? 1.8 : 0);
    state.player.z = boss.z - (
      action === "overhead" ? 5.8
        : action === "grab" || action === "lazyGrip" ? 5.4
          : action === "fourSides" || action === "crossSweep" || action === "prayerClap" ? 6.2
            : 4.6
    );
    state.player.group.position.set(state.player.x, 0, state.player.z);
    state.player.group.visible = action === "wake" || action === "grab" || action === "lazyGrip" ||
      action === "prayerClap" || action === "fourSides" || action === "crossSweep";

    var started = false;
    if (action === "wake") {
      encounter.phase = 0;
      boss.hp = boss.maxHp * SLOTH_ARCHBISHOP_WAKE_HP_RATIO;
      started = beginSlothArchbishopWake(encounter);
    } else if (action === "guard") {
      encounter.phase = previewFinalPhase ? 2 : 1;
      boss.hp = boss.maxHp * 0.66;
      started = beginSlothArchbishopGuard(encounter, { id: "solo", entity: state.player });
    } else if (action === "sweep") {
      encounter.phase = previewFinalPhase ? 2 : 1;
      boss.hp = boss.maxHp * (previewFinalPhase ? 0.34 : 0.66);
      started = beginSlothArchbishopSweep(encounter, { id: "solo", entity: state.player });
    } else if (action === "overhead") {
      encounter.phase = previewFinalPhase ? 2 : 1;
      boss.hp = boss.maxHp * (previewFinalPhase ? 0.34 : 0.66);
      started = beginSlothArchbishopSkySlam(encounter);
    } else if (action === "prayerClap") {
      encounter.phase = 1;
      boss.hp = boss.maxHp * 0.66;
      started = beginSlothArchbishopPrayerClap(encounter, { id: "solo", entity: state.player });
    } else if (action === "lazyGrip") {
      encounter.phase = 1;
      boss.hp = boss.maxHp * 0.66;
      started = beginSlothArchbishopLazyGrip(encounter, { id: "solo", entity: state.player });
    } else if (action === "fourSides") {
      encounter.phase = 2;
      boss.hp = boss.maxHp * 0.34;
      boss.speed = SLOTH_ARCHBISHOP_SPIDER_SPEED;
      started = beginSlothArchbishopFourSides(encounter, { id: "solo", entity: state.player });
    } else if (action === "crossSweep") {
      encounter.phase = 2;
      boss.hp = boss.maxHp * 0.34;
      boss.speed = SLOTH_ARCHBISHOP_SPIDER_SPEED;
      started = beginSlothArchbishopCrossSweep(encounter, { id: "solo", entity: state.player });
    } else if (action === "spiderrise") {
      encounter.phase = 1;
      boss.hp = boss.maxHp * SLOTH_ARCHBISHOP_SPIDER_HP_RATIO;
      started = beginSlothArchbishopSpiderRise(encounter);
    } else if (action === "grab") {
      encounter.phase = 2;
      boss.hp = boss.maxHp * 0.34;
      boss.speed = SLOTH_ARCHBISHOP_SPIDER_SPEED;
      started = beginSlothArchbishopGrab(encounter, { id: "solo", entity: state.player });
    } else {
      encounter.phase = 2;
      boss.hp = boss.maxHp * 0.2;
      boss.speed = SLOTH_ARCHBISHOP_SPIDER_SPEED;
      updateSlothArchbishopVisuals(encounter, 0);
      started = defeatSlothArchbishop({ type: "preview" });
    }
    if (!started) return false;
    updateSlothOrbitShield(encounter, 0);
    if (encounter.orbitShieldUnlocked) {
      encounter.orbitShieldTimer = SLOTH_ARCHBISHOP_ORBIT_SHIELD_REVEAL_DURATION;
    }

    var defaultProgress = action === "death" ? 0.42
      : action === "overhead" ? 0.44
        : action === "crossSweep" ? 0.36
          : action === "fourSides" ? 0.4
            : action === "prayerClap" ? 0.5
              : action === "lazyGrip" ? 0.46
                : 0.5;
    var previewProgress = clamp(
      Number.isFinite(Number(actionProgress)) ? Number(actionProgress) : defaultProgress,
      0,
      0.995
    );
    if (action === "death") {
      encounter.previewDeathProgress = previewProgress;
      updateSlothArchbishopDeathVisual(encounter, 0);
    } else {
      boss.actionDuration = 999;
      boss.actionTimer = boss.actionDuration * previewProgress;
      if (action === "overhead" || action === "prayerClap" || action === "fourSides" || action === "crossSweep") {
        for (var targetIndex = 0; targetIndex < encounter.slamTargets.length; targetIndex++) {
          var target = encounter.slamTargets[targetIndex];
          var previewAction = action === "overhead" ? "skySlam" : action;
          target.resolved = previewProgress >= getSlothArchbishopActionImpactProgress(encounter, previewAction);
        }
      }
      updateSlothArchbishopVisuals(encounter, 0);
    }
    cameraTarget.set(state.player.x, 0, state.player.z);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    updateSlothArchbishopHud();
    render();
    return getSlothArchbishopDiagnostics();
  }

  function setupGhostTrainPreview(closeup) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.wave10BossKind = "ghostTrain";
    state.paused = false;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 3);
    var heading = Math.PI / 2;
    var engineX = center.x + (closeup ? 3.2 : GHOST_TRAIN_TAIL_DISTANCE * 0.48);
    var encounter = startGhostTrainEncounter({
      x: engineX,
      z: center.z,
      heading: heading,
      preview: true,
      aiEnabled: false,
      freezeMotion: true,
      silent: true,
    });
    if (!encounter) return false;
    encounter.action = closeup ? "broadside" : "spectral";
    encounter.attackKind = closeup ? "broadside" : "spectral";
    encounter.actionDuration = 999;
    encounter.actionTimer = 999;
    encounter.boss.action = encounter.action;
    encounter.boss.actionDuration = 999;
    encounter.boss.actionTimer = 999;
    encounter.materialized = !!closeup;
    encounter.vulnerable = !!closeup;
    encounter.attackSide = 1;
    for (var segmentIndex = 0; segmentIndex < encounter.segments.length; segmentIndex++) {
      setGhostTrainSegmentForm(
        encounter.segments[segmentIndex],
        !!closeup,
        !!closeup && segmentIndex === encounter.activeTailIndex,
        0
      );
    }
    if (state.player) {
      state.player.x = closeup ? engineX - GHOST_TRAIN_TAIL_DISTANCE * 0.5 : center.x;
      state.player.z = closeup ? center.z : center.z - 4;
      state.player.invuln = 999;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    camera.zoom = closeup ? 1.55 : 0.72;
    camera.updateProjectionMatrix();
    cameraTarget.set(closeup ? engineX - GHOST_TRAIN_TAIL_DISTANCE * 0.5 : center.x, 0, center.z);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    updateGhostTrainAttachedTransforms(encounter, 0);
    updateGhostTrainTrackVisual(encounter);
    updateModeClass();
    updateHud();
    render();
    return getGhostTrainDiagnostics();
  }

  function setupOilBaronPreview(closeup, showDeal) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.wave10BossKind = "oilBaron";
    state.paused = false;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 3.2);
    var encounter = startOilBaronEncounter({
      x: center.x,
      z: center.z,
      preview: true,
      aiEnabled: false,
      silent: true,
    });
    if (!encounter) return false;
    encounter.boss.walkPhase = 1.06;
    encounter.boss.moveAmount = closeup ? 0.34 : 0.14;
    var previewDerricks = [
      { x: center.x - 13.8, z: center.z + 8.2, radius: 10.8, angle: 0.5, burn: 0 },
      { x: center.x + 14.2, z: center.z + 8.8, radius: 9.2, angle: -0.42, burn: 4.8 },
      { x: center.x + 14.8, z: center.z - 8.5, radius: 7.2, angle: 1.1, burn: 0 },
    ];
    for (var i = 0; i < previewDerricks.length; i++) {
      var spec = previewDerricks[i];
      var point = findNearestClearGroundPoint(spec.x, spec.z, 1.3);
      var oilAge = OIL_BARON_OIL_GROW_TIME * clamp(
        (spec.radius - OIL_BARON_OIL_START_RADIUS) / (OIL_BARON_OIL_MAX_RADIUS - OIL_BARON_OIL_START_RADIUS),
        0,
        1
      );
      var derrick = spawnOilDerrick(point.x, point.z, {
        instant: true,
        silent: true,
        angle: spec.angle,
        oilRadius: spec.radius,
        oilAge: oilAge,
        burnTime: spec.burn,
      });
      if (derrick && i === 2) derrick.igniteWarning = OIL_BARON_IGNITE_WARNING * 0.58;
    }
    if (showDeal) beginOilBaronBribe(encounter);
    var dealCloseup = !!(closeup && showDeal && encounter.bribeChest);
    if (dealCloseup) {
      // Visual-QA framing: freeze the offer before proximity can accept it and isolate the prop.
      encounter.bribeState = "preview";
      encounter.bribeTimeLeft = OIL_BARON_BRIBE_OFFER_TIME;
      encounter.boss.group.visible = false;
      for (var hiddenDerrickIndex = 0; hiddenDerrickIndex < encounter.derricks.length; hiddenDerrickIndex++) {
        encounter.derricks[hiddenDerrickIndex].group.visible = false;
      }
    }
    if (state.player) {
      state.player.x = dealCloseup ? encounter.bribeChestX : center.x;
      state.player.z = dealCloseup ? encounter.bribeChestZ : center.z - (closeup ? 3.4 : 8.5);
      state.player.invuln = 999;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    camera.zoom = dealCloseup ? 3.35 : (closeup ? 1.9 : 0.78);
    camera.updateProjectionMatrix();
    if (closeup && showDeal && encounter.bribeChest) {
      cameraTarget.set(encounter.bribeChestX, 0, encounter.bribeChestZ + 0.18);
    } else {
      cameraTarget.set(center.x, 0, center.z + (closeup ? 0.3 : 1.4));
    }
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    updateOilDerricks(encounter, 0, true);
    updateOilBaronVisuals(encounter, 0);
    updateModeClass();
    updateHud();
    render();
    return getOilBaronDiagnostics();
  }

  function setupGhostTrainAttackPreview() {
    if (!setupGhostTrainPreview(true)) return false;
    var encounter = state.ghostTrain;
    if (!encounter || !encounter.boss) return false;
    encounter.action = "broadside";
    encounter.attackKind = "broadside";
    encounter.attackSide = 1;
    encounter.actionDuration = 4.6;
    encounter.actionTimer = 4.05;
    encounter.lastCannonStep = -1;
    encounter.boss.action = encounter.action;
    encounter.boss.actionDuration = encounter.actionDuration;
    encounter.boss.actionTimer = encounter.actionTimer;
    updateGhostTrainCannonSchedule(encounter, true);
    for (var ballIndex = 0; ballIndex < state.ghostTrainCannonballs.length; ballIndex++) {
      var ball = state.ghostTrainCannonballs[ballIndex];
      ball.x += ball.dirX * 3.2;
      ball.z += ball.dirZ * 3.2;
      ball.oldX = ball.x;
      ball.oldZ = ball.z;
      ball.speed = 0;
      ball.life = 999;
      ball.trailTimer = 999;
      ball.cosmeticOnly = true;
      if (ball.mesh) {
        updateGhostTrainCannonballVisual(ball.mesh, ball.x, ball.y, ball.z, ball.angle, ball.spin || 0, 1);
      }
      updateGhostTrainCannonTrajectoryForBall(ball);
    }
    updateGhostTrainAttachedTransforms(encounter, 0);
    updateGhostTrainTrackVisual(encounter);
    updateGhostTrainHud();
    render();
    return getGhostTrainDiagnostics();
  }

