  function setupDoppelgangerPyrotechnicianTestScene() {
    resetRun("playing");
    setIntroActive(false);
    setupMaxPyrotechnicianTestPlayer();
    if (!state.player) return false;

    clearDoppelgangerEncounter();
    clearBossEncounters();
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.spawnTimer = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.waveTimer = 0;
    state.paused = false;

    var playerSpot = findNearestClearGroundPoint(
      0,
      -8,
      Math.max(0.8, state.player.radius + 0.35)
    );
    state.player.x = playerSpot && Number.isFinite(playerSpot.x)
      ? playerSpot.x
      : 0;
    state.player.z = playerSpot && Number.isFinite(playerSpot.z)
      ? playerSpot.z
      : -8;
    resolveMoverPosition(state.player, state.player.radius, 0);
    state.player.group.position.set(
      state.player.x,
      0,
      state.player.z
    );

    var cloneSpot = findNearestClearGroundPoint(
      state.player.x,
      state.player.z + 13,
      DOPPELGANGER_SCOUT_RADIUS + 0.18
    );
    var encounter = beginDoppelgangerScoutAfterBoss(
      null,
      BOSS_FIRST_WAVE
    );
    if (!encounter || !encounter.scout) return false;
    encounter.scout.x =
      cloneSpot && Number.isFinite(cloneSpot.x)
        ? cloneSpot.x
        : state.player.x;
    encounter.scout.z =
      cloneSpot && Number.isFinite(cloneSpot.z)
        ? cloneSpot.z
        : state.player.z + 13;
    encounter.scout.lastX = encounter.scout.x;
    encounter.scout.lastZ = encounter.scout.z;
    encounter.scout.group.position.set(
      encounter.scout.x,
      0,
      encounter.scout.z
    );
    encounter.lastEatX = encounter.scout.x;
    encounter.lastEatZ = encounter.scout.z;
    if (!startDoppelgangerBossEncounter(encounter)) return false;
    encounter.transformTimer = 0;
    updateDoppelgangerBossEncounter(encounter, 0);

    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.spawnTimer = 0;
    state.waveSuspended = true;
    var clone = encounter.clones && encounter.clones[0];
    if (!clone) return false;
    state.pointerWorld.x = clone.x;
    state.pointerWorld.z = clone.z;
    pointerHit.set(clone.x, 0, clone.z);
    updateAim();
    cameraTarget.set(state.player.x, 0, state.player.z);
    camera.position.set(
      cameraTarget.x + cameraBaseOffset.x,
      cameraBaseOffset.y,
      cameraTarget.z + cameraBaseOffset.z
    );
    camera.lookAt(cameraTarget);
    updateDoppelgangerHud();
    updateModeClass();
    updateHud();
    render();

    document.body.classList.add("test-stand-active");
    document.body.setAttribute(
      "data-test-stand",
      "doppelganger-pyrotechnician"
    );
    document.body.setAttribute(
      "data-test-stand-player-class",
      state.playerClass
    );
    document.body.setAttribute(
      "data-test-stand-weapon",
      state.weapon
    );
    document.body.setAttribute(
      "data-test-stand-launcher-upgrade",
      state.launcherUpgrade
    );
    document.body.setAttribute(
      "data-test-stand-enemy-count",
      String(state.enemies.length)
    );
    document.body.setAttribute(
      "data-test-stand-clone-count",
      String(encounter.clones.length)
    );
    setPauseMenuOpen(true);
    return true;
  }

