  function updateEnemyBestiaryAnimationPreview(dt) {
    state.time += dt;
    for (var index = 0; index < state.enemies.length; index++) {
      var enemy = state.enemies[index];
      if (!enemy || enemy.active === false || !enemy.group) continue;
      var miner = enemy.type === "armoredMiner";
      enemy.walkPhase += dt * (miner ? 3.1 : 2.65);
      enemy.moveAmount = miner ? 0.72 : 0.48;
      enemy.renderVisible = true;
      if (enemy.type === "gravePreacher") {
        var ritualCycle = (state.time + index * 0.47) % 4.8;
        if (ritualCycle < GRAVE_PREACHER_PRAYER_TIME) {
          enemy.preacherPrayerTimer = GRAVE_PREACHER_PRAYER_TIME - ritualCycle;
          enemy.preacherPulse = Math.sin(ritualCycle / GRAVE_PREACHER_PRAYER_TIME * Math.PI) * 0.9;
        } else {
          enemy.preacherPrayerTimer = 0;
          enemy.preacherPulse = 0;
        }
      }
      updateZombieVisual(enemy);
      enemy.group.position.x = enemy.x;
      enemy.group.position.z = enemy.z;
      enemy.group.rotation.y = 0;
    }
    syncZombieInstanceBatches();
  }

  function setupLandEaterVfxPreview(mode, requestedProgress) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.wave10BossKind = "landEater";
    state.paused = true;
    state.time = 12.35;

    var previewMode = String(mode || "devour").toLowerCase();
    var numericProgress = requestedProgress == null || requestedProgress === ""
      ? NaN
      : Number(requestedProgress);
    var previewProgress = Number.isFinite(numericProgress)
      ? clamp(numericProgress, 0, 1)
      : previewMode === "zigzag-active" ? 0.48 : 0.68;
    var focusCell = getLandEaterCellAtWorld(0, 0) ||
      getLandEaterCellBounds(getLandEaterCellId(
        Math.floor(LAND_EATER_GRID_COLUMNS * 0.5),
        Math.floor(LAND_EATER_GRID_ROWS * 0.5)
      ));
    if (!focusCell) return false;

    var encounter = startLandEaterEncounter({
      x: focusCell.x,
      z: focusCell.z,
      aiEnabled: false,
      suppressEffects: false,
    });
    if (!encounter) return false;
    encounter.boss.hp = encounter.boss.maxHp * 0.22;
    updateLandEaterPhase(encounter);

    var focusX = focusCell.x;
    var focusZ = focusCell.z;
    if (
      previewMode === "devour" ||
      previewMode === "devour-tunnel" ||
      previewMode === "devour-impact"
    ) {
      setLandEaterAction(encounter, "devour", { targetCellId: focusCell.id });
      var impactAt = encounter.warningDuration + LAND_EATER_DEVOUR_DIVE_TIME;
      if (previewMode === "devour-tunnel") {
        encounter.actionTimer =
          encounter.devourTunnelDuration * previewProgress;
      } else if (previewMode === "devour-impact") {
        if (state.player) {
          state.player.x = -ARENA_W * 0.35;
          state.player.z = -ARENA_D * 0.35;
          state.player.group.position.set(state.player.x, 0, state.player.z);
        }
        encounter.actionTimer = impactAt;
        consumeLandEaterCell(encounter);
        updateParticles(0.28);
        updateVisualEffects(0.28);
      } else {
        encounter.actionTimer = Math.min(
          impactAt - 0.01,
          Math.max(0.01, impactAt * previewProgress)
        );
      }
      applyLandEaterDevourPath(encounter);
      if (previewMode === "devour-tunnel") {
        focusX = (encounter.boss.x + focusCell.x) * 0.5;
        focusZ = (encounter.boss.z + focusCell.z) * 0.5;
        camera.zoom = 0.46;
      } else {
        camera.zoom = 0.84;
      }
    } else if (
      previewMode === "hunt" ||
      previewMode === "burrow-bite"
    ) {
      var huntRoute = [
        { x: focusCell.x - 34, z: focusCell.z - 22 },
        { x: focusCell.x + 24, z: focusCell.z + 16 },
      ];
      setLandEaterAction(encounter, "burrow", {
        route: huntRoute,
        targetPlayerId: "preview",
      });
      var huntTravelDuration = Math.max(
        0.1,
        encounter.actionDuration -
          LAND_EATER_BURROW_EMERGE_TIME -
          LAND_EATER_BURROW_STRIKE_TIME
      );
      if (previewMode === "hunt") {
        encounter.actionTimer = huntTravelDuration * previewProgress;
      } else {
        encounter.actionTimer =
          huntTravelDuration +
          LAND_EATER_BURROW_EMERGE_TIME +
          LAND_EATER_BURROW_STRIKE_TIME * previewProgress;
      }
      applyLandEaterBurrowPath(encounter);
      focusX = encounter.boss.x;
      focusZ = encounter.boss.z;
      camera.zoom = previewMode === "hunt" ? 0.68 : 0.82;
    } else {
      var route = buildLandEaterZigzagRoute(encounter, 1);
      setLandEaterAction(encounter, "zigzag", { route: route });
      var telegraphDuration = getLandEaterZigzagTelegraphDuration(encounter);
      if (
        previewMode === "zigzag-active" ||
        previewMode === "zigzag-devour" ||
        previewMode === "zigzag-bounce"
      ) {
        var motionPreviewProgress = previewProgress;
        if (previewMode === "zigzag-bounce") {
          var firstSegmentLength = Math.hypot(
            route[1].x - route[0].x,
            route[1].z - route[0].z
          );
          var routeLength = firstSegmentLength;
          for (var routeIndex = 2; routeIndex < route.length; routeIndex++) {
            routeLength += Math.hypot(
              route[routeIndex].x - route[routeIndex - 1].x,
              route[routeIndex].z - route[routeIndex - 1].z
            );
          }
          motionPreviewProgress = firstSegmentLength / Math.max(0.001, routeLength);
        }
        encounter.actionTimer = telegraphDuration +
          (encounter.actionDuration - telegraphDuration) * motionPreviewProgress;
        updateLandEaterZigzag(encounter, 0, true);
        if (previewMode === "zigzag-devour") {
          if (state.player) {
            state.player.x = 0;
            state.player.z = ARENA_D * 0.5 - 6;
            state.player.group.position.set(
              state.player.x,
              0,
              state.player.z
            );
          }
          consumeLandEaterZigzagCellsThroughDistance(
            encounter,
            encounter.zigzagTravelDistance
          );
        }
        if (previewMode === "zigzag-bounce") {
          spawnLandEaterBounceFx(encounter, route[1].x, route[1].z, 1);
          updateParticles(0.18);
          updateVisualEffects(0.18);
        }
      } else {
        encounter.actionTimer = Math.max(
          0.01,
          Math.min(telegraphDuration - 0.01, telegraphDuration * previewProgress)
        );
      }
      focusX = previewMode === "zigzag-bounce" ? route[1].x : 0;
      focusZ = previewMode === "zigzag-bounce" ? route[1].z : 2;
      camera.zoom = previewMode === "zigzag-bounce" ? 0.66 : 0.29;
    }

    if (state.player) {
      state.player.x = focusX;
      state.player.z = focusZ;
      state.player.invuln = 999;
      state.player.group.position.set(focusX, 0, focusZ);
      state.player.group.visible = false;
    }
    camera.updateProjectionMatrix();
    updateLandEaterVisual(encounter, 0);
    updateLandEaterHud();
    updateModeClass();
    updateHud();
    render();
    return getLandEaterDiagnostics();
  }

  function stockRandomWave10Level13TestAmmo() {
    Object.keys(WEAPONS).forEach(function (weaponId) {
      var weapon = WEAPONS[weaponId];
      state.ammo[weaponId] = getWeaponMagazine(weapon);
      state.ammoReserve[weaponId] = Math.max(
        state.ammoReserve[weaponId] || 0,
        RANDOM_WAVE10_LEVEL13_TEST_AMMO_RESERVE
      );
      state.reloadTimers[weaponId] = 0;
    });
    if (hasAllRightAllLeft()) {
      setDualRevolverHandAmmoFromAggregate(state.ammo.revolver);
    }
  }

  function ensureRandomWave10Level13RerollButton() {
    var button = document.getElementById("wave10-test-reroll");
    if (button) return button;
    button = document.createElement("button");
    button.id = "wave10-test-reroll";
    button.className = "test-stand-reroll";
    button.type = "button";
    button.textContent = "Другой босс";
    button.setAttribute("aria-label", "Перезапустить стенд с другим случайным боссом");
    button.addEventListener("pointerdown", function (event) {
      event.stopPropagation();
    });
    button.addEventListener("click", function (event) {
      event.preventDefault();
      event.stopPropagation();
      setupRandomWave10Level13TestScene();
    });
    document.body.appendChild(button);
    return button;
  }

  function setupRandomWave10Level13TestScene() {
    var previousBossKind = randomWave10Level13TestLastBossKind;
    resetRun("playing");
    setIntroActive(false);
    state.bossRotationLastKind = previousBossKind;
    startWaveForTest(BELL_RINGER_WAVE, "random");
    if (!state.player) return false;
    randomWave10Level13TestLastBossKind = state.wave10BossKind || previousBossKind;

    // Award every level in one transaction so the normal reward queue opens
    // with the class choice and leaves every build decision to the player.
    var targetLevel = 13;
    var requiredXp = -state.xp;
    for (var level = state.level; level < targetLevel; level++) {
      requiredXp += getXpToNextLevel(level);
    }
    if (requiredXp > 0) addXp(requiredXp, state.player.x, state.player.z);
    stockRandomWave10Level13TestAmmo();

    document.body.classList.add("test-stand-active");
    document.body.setAttribute("data-test-stand-level", String(state.level));
    document.body.setAttribute("data-test-stand-boss", state.wave10BossKind || "");
    document.body.setAttribute(
      "data-test-stand-ammo-reserve",
      String(RANDOM_WAVE10_LEVEL13_TEST_AMMO_RESERVE)
    );
    ensureRandomWave10Level13RerollButton();
    updateModeClass();
    updateHud();
    render();
    return state.level === targetLevel && !!state.wave10BossKind;
  }

  function applyMarshalPreviewFromQuery() {
    var params = new URLSearchParams(window.location.search || "");
    var preview = (params.get("preview") || "").toLowerCase();
    if (!preview) return false;
    if (preview === "enemy-bestiary") return !!setupEnemyBestiaryPreview("all");
    if (preview === "enemy-miner") return !!setupEnemyBestiaryPreview("miner");
    if (preview === "enemy-miner-damaged") return !!setupEnemyBestiaryPreview("miner-damaged");
    if (preview === "enemy-preacher") return !!setupEnemyBestiaryPreview("preacher");
    if (preview === "land-eater-devour" || preview === "land-eater-devour-warning") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("devour", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-devour-impact") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("devour-impact", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-devour-tunnel") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("devour-tunnel", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-hunt") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("hunt", params.get("progress"));
      }, 0);
      return true;
    }
    if (
      preview === "land-eater-bite" ||
      preview === "land-eater-burrow-bite"
    ) {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("burrow-bite", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-zigzag" || preview === "land-eater-zigzag-telegraph") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("zigzag", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-zigzag-active") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("zigzag-active", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-zigzag-devour") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("zigzag-devour", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "land-eater-zigzag-bounce") {
      window.setTimeout(function () {
        setupLandEaterVfxPreview("zigzag-bounce", params.get("progress"));
      }, 0);
      return true;
    }
    if (preview === "wave10-level13-test") return !!setupRandomWave10Level13TestScene();
    if (
      preview === "doppelganger-launcher-test" ||
      preview === "doppelganger-pyrotechnician-test" ||
      preview === "doppelganger-fire-launcher-test"
    ) return !!setupDoppelgangerPyrotechnicianTestScene();
    if (preview === "land-eater-rifle-test") return !!setupLandEaterRifleTestScene();
    if (preview === "hordeheart-rifle-test") return !!setupHordeheartRifleTestScene();
    if (preview === "hordeheart-action") return !!setupHordeheartActionPreview(
      params.get("action"),
      params.get("progress"),
      params.get("variant"),
      params.get("size")
    );
    if (preview === "hordeheart-movement-lock") {
      return !!setupHordeheartActionPreview("fleshTide", params.get("progress"), "movement-lock");
    }
    if (preview === "hordeheart-repulse") {
      return !!setupHordeheartActionPreview("ribBloom", params.get("progress"), "proximity-repulse", params.get("size"));
    }
    if (preview === "hordeheart-crawl") return !!setupHordeheartCrawlPreview(params.get("size"), params.get("phase"));
    if (preview === "hordeheart-rib-bloom") return !!setupHordeheartActionPreview("ribBloom", params.get("progress"));
    if (preview === "hordeheart-systole") return !!setupHordeheartActionPreview("systole", params.get("progress"));
    if (preview === "hordeheart-flesh-tide") return !!setupHordeheartActionPreview("fleshTide", params.get("progress"));
    if (preview === "hordeheart-pincer") return !!setupHordeheartActionPreview("pincer", params.get("progress"));
    if (preview === "hordeheart-rush") return !!setupHordeheartActionPreview("rush", params.get("progress"));
    if (preview === "hordeheart-death" || preview === "hordeheart-half-death") return !!setupHordeheartDeathPreview(params.get("progress"));
    if (preview === "hordeheart-horde") return !!setupHordeheartPreview("horde", params.get("progress"));
    if (preview === "hordeheart-gather") return !!setupHordeheartPreview("gather", params.get("progress"));
    if (preview === "hordeheart" || preview === "hordeheart-whole") return !!setupHordeheartPreview("whole");
    if (preview === "hordeheart-split1") return !!setupHordeheartPreview("split1", params.get("progress"));
    if (preview === "hordeheart-halves") return !!setupHordeheartPreview("halves");
    if (preview === "hordeheart-split2") return !!setupHordeheartPreview("split2", params.get("progress"));
    if (preview === "hordeheart-quarters" || preview === "hordeheart-final") return !!setupHordeheartPreview("quarters");
    if (preview === "sloth-archbishop" || preview === "archbishop-of-sloth") return !!setupSlothArchbishopPreview("sleep");
    if (preview === "sloth-archbishop-model") return !!setupSlothArchbishopModelPreview();
    if (preview === "sloth-archbishop-awake") return !!setupSlothArchbishopPreview("walk");
    if (preview === "sloth-archbishop-orbit-shield") return !!setupSlothArchbishopPreview("shield");
    if (preview === "sloth-archbishop-spider") return !!setupSlothArchbishopPreview("spider");
    if (preview === "sloth-archbishop-action") {
      return !!setupSlothArchbishopActionPreview(params.get("action"), params.get("progress"), params.get("phase"));
    }
    if (preview === "sloth-archbishop-coach-gun-test" || preview === "sloth-archbishop-shotgun-test") {
      return !!setupSlothArchbishopCoachGunTestScene();
    }
    if (preview === "ghost-train") return !!setupGhostTrainPreview(false);
    if (preview === "ghost-train-closeup" || preview === "ghost-train-materialized") return !!setupGhostTrainPreview(true);
    if (preview === "ghost-train-attack") return !!setupGhostTrainAttackPreview();
    if (preview === "ghost-train-attack-warning") return !!setupGhostTrainCannonWarningPreview();
    if (preview === "ghost-train-death") return !!setupGhostTrainDeathPreview();
    if (preview === "oil-baron-rifle-test") return !!setupOilBaronRifleTestScene();
    if (preview === "oil-baron-cane") return !!setupOilBaronCaneTelegraphPreview();
    if (preview === "oil-baron-cane-shot") return !!setupOilBaronCaneShotPreview();
    if (preview === "oil-baron-slam") return !!setupOilBaronGroundSlamPreview();
    if (preview === "oil-baron-star") return !!setupOilBaronStarPreview();
    if (preview === "oil-baron") return !!setupOilBaronPreview(false, false);
    if (preview === "oil-baron-closeup") return !!setupOilBaronPreview(true, false);
    if (preview === "oil-baron-deal") return !!setupOilBaronPreview(false, true);
    if (preview === "oil-baron-deal-closeup") return !!setupOilBaronPreview(true, true);
    if (preview === "bell-ringer") return !!setupBellRingerPreview(false);
    if (preview === "bell-ringer-closeup") return !!setupBellRingerPreview(true);
    if (preview === "bell-ringer-attack") return !!setupBellRingerAttackPreview();
    if (preview === "bell-ringer-ascension") return !!setupBellRingerAscensionPreview();
    if (preview === "bell-ringer-last-stand") return !!setupBellRingerLastStandPreview();
    if (preview === "bell-ringer-bell-drop") return !!setupBellRingerBellDropPreview();
    if (preview === "bell-church") return !!setupBellChurchPreview();
    if (preview === "bell-ringer-map") return !!setupBellRingerMapPreview();
    if (preview === "bell-ringer-rifle-test") return !!setupBellRingerRifleTestScene();

    var galleries = {
      "marshal-breach-a": {
        branch: "breachMarshal",
        subtitle: "Display only · Breach Marshal · I",
        ids: ["doorKicker", "doubleTap", "lastWord", "shellCatcher", "buckAndBall"],
      },
      "marshal-breach-b": {
        branch: "breachMarshal",
        subtitle: "Display only · Breach Marshal · II",
        ids: ["rideTheRecoil", "bonebreaker", "noTimeToBleed", "packedBuckshot", "hardCast"],
      },
      "marshal-breach-c": {
        branch: "breachMarshal",
        subtitle: "Display only · Breach Marshal · III",
        ids: ["roomSweeper", "rollingThunder", "sheriffsPace", "holdTheDoor", "powderCurtain", "masterKey"],
      },
      "marshal-grave-a": {
        branch: "graveWarden",
        subtitle: "Display only · Grave Warden · I",
        ids: ["rockSalt", "stillness", "lastRites", "graveTithe", "heavensBounty"],
      },
      "marshal-grave-b": {
        branch: "graveWarden",
        subtitle: "Display only · Grave Warden · II",
        ids: ["passingJudgment", "purifyingSalt", "hallowedGround", "fineChoke", "sanctifiedLead"],
      },
    };

    var knownPreview =
      preview === "marshal-class" ||
      preview === "marshal-subclasses" ||
      preview === "marshal-gameplay" ||
      preview === "marshal-gameplay-breach" ||
      preview === "pale-deputy" ||
      !!galleries[preview];
    if (!knownPreview) return false;

    resetRun("playing");
    setIntroActive(false);

    if (preview === "marshal-class") {
      state.level = CLASS_CHOICE_LEVEL;
      state.mode = "playing";
      maybeOfferClassChoice();
      return true;
    }

    state.playerClass = "marshal";
    state.classChoiceOffered = true;
    grantWeapon("coachGun", true);

    if (preview === "pale-deputy") {
      state.level = 19;
      state.marshalUpgrade = "graveWarden";
      state.marshalUpgradeOffered = true;
      state.upgradeCounts.lastRites = 1;
      releaseAllEnemiesToPool();
      state.spawnLeft = 0;
      state.waveInitialPressureLeft = 0;
      state.waveSuspended = true;
      state.player.aimAngle = Math.PI * 0.84;
      state.pointerWorld.x = state.player.x + Math.sin(state.player.aimAngle) * 5;
      state.pointerWorld.z = state.player.z + Math.cos(state.player.aimAngle) * 5;
      var previewDeputy = tryRaisePaleDeputy(state.player.x + 0.5, state.player.z + 0.2);
      if (previewDeputy) previewDeputy.previewDisplay = true;
      state.player.group.visible = false;
      camera.zoom = 3.4;
      setWeaponVisual("coachGun");
      updateModeClass();
      updateHud();
      render();
      return true;
    }

    if (preview === "marshal-subclasses") {
      state.level = MARSHAL_UPGRADE_LEVEL;
      state.mode = "playing";
      maybeOfferMarshalUpgradeChoice();
      return true;
    }

    var gallery = galleries[preview];
    if (gallery) {
      state.level = 19;
      state.marshalUpgrade = gallery.branch;
      state.marshalUpgradeOffered = true;
      state.standardUpgradeLevel = 19;
      state.standardUpgradePending = true;
      state.standardUpgradeChoices = gallery.ids.map(getStandardUpgradeById).filter(Boolean);
      state.mode = "level-up";
      setWeaponVisual("coachGun");
      renderStandardUpgradeChoices();
      var previewHeading = levelUpPanel ? levelUpPanel.querySelector("h2") : null;
      if (previewHeading) previewHeading.textContent = "Icon Showcase";
      if (levelUpSubtitle) levelUpSubtitle.textContent = gallery.subtitle;
      setPanel(levelUpPanel, true);
      setPanel(menu, false);
      setPanel(gameOverPanel, false);
      setPanel(classChoicePanel, false);
      setPanel(revolverUpgradePanel, false);
      setPanel(rifleUpgradePanel, false);
      setPanel(launcherUpgradePanel, false);
      setPanel(marshalUpgradePanel, false);
      updateModeClass();
      updateHud();
      render();
      return true;
    }

    if (preview === "marshal-gameplay" || preview === "marshal-gameplay-breach") {
      state.level = 19;
      state.marshalUpgrade = preview === "marshal-gameplay-breach" ? "breachMarshal" : "graveWarden";
      state.marshalUpgradeOffered = true;
      if (state.marshalUpgrade === "breachMarshal") {
        state.marshalBreachMomentumStacks = Math.round(clamp(
          Number(params.get("momentum")) || 0,
          0,
          COACH_GUN_BREACH_MOMENTUM_MAX
        ));
        state.marshalBreachMomentumTimer = state.marshalBreachMomentumStacks > 0
          ? 9999
          : 0;
        state.marshalBreachStepTimer = params.get("step") === "1"
          ? COACH_GUN_BREACH_STEP_TIME
          : 0;
        updateBreachMomentumPlayerVisual(state.player && state.player.group, state);
      }
      setWeaponVisual("coachGun");
      updateModeClass();
      updateHud();
      render();
      if (state.marshalUpgrade === "breachMarshal") {
        document.body.setAttribute(
          "data-breach-preview",
          JSON.stringify(getBreachMomentumVisualDiagnostics())
        );
      }
      return true;
    }

    return false;
  }

  function isRifleListenSceneRequested() {
    var params = new URLSearchParams(window.location.search || "");
    var value = (params.get("listen") || "").toLowerCase();
    return value === "rifle" || value === "winchester";
  }

  function setupRifleListenScene() {
    if (!state.player) return;
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.spawnTimer = 9999;
    state.waveSuspended = true;
    state.nextWaveTimer = 9999;
    state.playerClass = "ranger";
    state.classChoicePending = false;
    state.classChoiceOffered = true;
    grantWeapon("rifle", true);
    state.ammo.rifle = getWeaponMagazine(WEAPONS.rifle);
    state.ammoReserve.rifle = Math.max(state.ammoReserve.rifle || 0, 180);
    state.reloadTimers.rifle = 0;
    state.pointerWorld.x = state.player.x + 18;
    state.pointerWorld.z = state.player.z;
    pointerHit.set(state.pointerWorld.x, 0, state.pointerWorld.z);
    updateAim();
    updateHud();
    render();
  }

