        if (oilRevealElapsed > (oilBaronRevealMeasurement.replicaRevealMaxRenderMs || 0)) {
          oilBaronRevealMeasurement.replicaRevealMaxRenderMs = oilRevealElapsed;
          oilBaronRevealMeasurement.replicaRevealMaxRenderKind =
            oilBaronRevealMeasurement.replicaRevealLastRenderKind;
        }
        oilBaronRevealMeasurement.replicaRevealMeasureNextRender = false;
