  function runDoppelgangerPurifyingSaltReciprocityForTest(idOrIndex) {
    var clone = findDoppelgangerCloneForTest(idOrIndex);
    if (!clone) return null;
    var ownerId = getDoppelgangerOwnerId(clone);
    var playerOwnerId = String(clone.sourcePlayerId || "solo");
    var testSequence = 0;
    function addTestBullet(projectileOwnerId, faction) {
      var mesh = new THREE.Group();
      mesh.name = "purifying salt test projectile";
      mesh.position.set(2, 1, 0);
      dynamicRoot.add(mesh);
      var bullet = {
        type: "revolver",
        x: 2,
        y: 1,
        z: 0,
        hitRadius: 0.15,
        ownerPlayerId: projectileOwnerId,
        doppelgangerOwnerId:
          faction === "doppelganger" ? projectileOwnerId : "",
        faction: faction || "",
        playerAttackId:
          "purify-test:" + String(++testSequence),
        mesh: mesh,
        purifyingSaltTestProjectile: true,
      };
      state.bullets.push(bullet);
      return bullet;
    }
    function remainingTestOwners() {
      return state.bullets.filter(function (bullet) {
        return !!(bullet && bullet.purifyingSaltTestProjectile);
      }).map(function (bullet) {
        return String(bullet.ownerPlayerId || "");
      });
    }
    function clearTestBullets() {
      for (var i = state.bullets.length - 1; i >= 0; i--) {
        if (state.bullets[i] && state.bullets[i].purifyingSaltTestProjectile) {
          removeBullet(i);
        }
      }
    }
    var context = {
      startX: 0,
      startZ: 0,
      dirX: 1,
      dirZ: 0,
      range: 8,
      spread: 0.25,
      lagCompensationRadius: 0,
      acidCleansed: 0,
    };
    clearTestBullets();
    addTestBullet(playerOwnerId, "");
    addTestBullet(ownerId, "doppelganger");
    var cloneCleansed = 0;
    withDoppelgangerCombatContext(clone, function () {
      purifyAcidWithCoachGun(context);
      cloneCleansed = Math.max(0, context.acidCleansed || 0);
    });
    var afterCloneOwners = remainingTestOwners();
    addTestBullet(playerOwnerId, "");
    context.acidCleansed = 0;
    purifyAcidWithCoachGun(context);
    var playerCleansed = Math.max(0, context.acidCleansed || 0);
    var afterPlayerOwners = remainingTestOwners();
    clearTestBullets();
    return {
      ownerId: ownerId,
      playerOwnerId: playerOwnerId,
      cloneCleansed: cloneCleansed,
      afterCloneOwners: afterCloneOwners,
      playerCleansed: playerCleansed,
      afterPlayerOwners: afterPlayerOwners,
    };
  }

