    resolveDoppelgangerCloneHitForTest: function (idOrIndex, targetPlayerId) {
      var clone = findDoppelgangerCloneForTest(idOrIndex);
      if (!clone || !clone.progression || clone.active === false || clone.hp <= 0) return null;
      var targetEntry = null;
      if (isMultiplayerHostMatch()) {
        var requestedPlayer = targetPlayerId ? getMultiplayerPlayer(String(targetPlayerId)) : null;
        if (requestedPlayer && requestedPlayer.entity) {
          targetEntry = {
            id: requestedPlayer.id,
            player: requestedPlayer,
            entity: requestedPlayer.entity,
          };
        } else {
          targetEntry = findDoppelgangerTargetEntry(clone);
        }
      } else if (state.player) {
        targetEntry = { id: "solo", player: null, entity: state.player };
      }
      if (!targetEntry || !targetEntry.entity) return null;
      var target = targetEntry.entity;
      target.invuln = 0;
      var hpBefore = target.hp;
      var rawDamage = 0;
      var appliedDamage = withDoppelgangerCombatContext(clone, function () {
        rawDamage = getWeaponDamage(WEAPONS[clone.weapon] || WEAPONS.revolver);
        return damagePlayer(rawDamage, target, {
          type: "doppelganger",
          ownerPlayerId: getDoppelgangerOwnerId(clone),
          attackerId: getDoppelgangerOwnerId(clone),
          sourceClone: clone,
          direct: true,
        });
      });
      clone.lastRawDamage = rawDamage;
      clone.lastAppliedDamage = Math.max(0, Number(appliedDamage) || 0);
      updateHud();
      render();
      return {
        cloneId: String(clone.networkId || clone.id || ""),
        targetPlayerId: String(targetEntry.id || ""),
        weapon: clone.weapon,
        rawDamage: Number((Number(rawDamage) || 0).toFixed(6)),
        appliedDamage: Number((Number(appliedDamage) || 0).toFixed(6)),
        targetHpBefore: Number((Number(hpBefore) || 0).toFixed(6)),
        targetHpAfter: Number((Number(target.hp) || 0).toFixed(6)),
      };
    },
