      var ratio = requested === 1 ? 1 : requested === 2 ? LAND_EATER_PHASE_TWO_RATIO : LAND_EATER_PHASE_THREE_RATIO;
      encounter.active = true;
      encounter.defeated = false;
      encounter.boss.active = true;
