      opts.kind = kind || "main";
      var source = explodeGrenade(Number(x) || 0, Number(z) || 0, Math.max(0.2, Number(radius) || getLauncherBlastRadius()), Math.max(0.1, Number(damage) || getLauncherBlastDamage()), opts);
