      var sampleCount = clamp(Math.floor(Number(iterations) || 1), 1, 500);
      var offers = [];
      var seen = Object.create(null);
      state.standardUpgradeLevel = sampleLevel;
      try {
        for (var sampleIndex = 0; sampleIndex < sampleCount; sampleIndex++) {
          var ids = rollStandardUpgradeChoices().map(function (spec) { return spec.id; });
          offers.push(ids);
          for (var idIndex = 0; idIndex < ids.length; idIndex++) seen[ids[idIndex]] = true;
        }
      } finally {
        state.standardUpgradeLevel = previousLevel;
      }
      return {
        level: sampleLevel,
        offers: offers,
        seen: Object.keys(seen),
      };
